quests[25725] = { id = 25725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fenbush Berries", description = "We're good on provisions, but we're in need of some medicine. Half the camp's fiercely hung over, and a remedy's in order.\n\nLuckily, I know a good folk remedy taught to me by my dear old mum. We just need some local ingredients.\n\nGather me some fenbush berries, if you would. They keep to where there's water and shade, so look along the shore and near other plants.", sourceObjective = "Collect 15 Handfuls of Fenberries.", progress = "How much've you got?", completion = "These'll do nicely. I'll have the lads back on their feet as soon as I make these somewhat edible.", sourceObjectiveStatus = "unverified-source-field" }
quests[25726] = { id = 25726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dumpy Job", description = "Alright, I need you to help me find my dumpy level.\n\nWhat's that look for? That's right! I said my dumpy level! It's a piece of significant surveying equipment!\n\nI didn't name the bloody thing, alright? Go look it up! All I did was leave it on a rock long enough for one of those horrible oozes to swallow it up. The place is crawling with 'em, but one of them should still have it inside.", sourceObjective = "Obtain a Dumpy Level from a Silty Ooze.", progress = "Did you find the dumpy?", completion = "Oh good, it's undamaged! Thanks a lot.\n\nYou ah, you might want to wipe yourself off a bit there.", sourceObjectiveStatus = "unverified-source-field" }
quests[25727] = { id = 25727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drungeld Glowerglare", description = "The Dark Iron clan is up to no good out here. And if that surprises you, you're thicker than the addled blotters over in that tent. Muradin may pay lip service to those sooty cretins back in Ironforge, but out here all bets are off.\n\nWe had a raid against the camp last night, and one raid is too many. Their leader's a stout fellow by the name of Glowerglare, and he's hiding in the cave on the south bank of the river.\n\nBring me Glowerglare's beard as proof he's no longer a threat to us and Ironforge.", sourceObjective = "Kill Drungeld Glowerglare and take his beard.", progress = "Let's see it, then.", completion = "Good riddance to bad rubbish! I'll burn the foul thing later so it doesn't stink up the camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[25728] = { id = 25728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. P's Wild Ride", description = "Now Mr. P just needs an angel to help him navigate. Will you be that angel, <mister/miss>? With you helping we can go out into the crag and kill bunches and bunches of Horde! Waddya say? Come on, <mister/miss>! PRETTY PLEASE WITH SUGAR ON TOP?\n\nIf we kill enough Horde, Mr. Fallowmere will buy us all ice cream!", sourceObjective = "Kill 20 Goblin Technicians and 5 Goblin Harvesters.", completion = "<Lord Fallowmere coughs.>\n\nThis is awkward...\n\nGood job out there with the robot. You caught me a little off guard. I didn't realize the little girl was so...\n\n<Lord Fallowmere points to his temple and twirls his finger around.>\n\nSpecial...\n\nWell, whatever gets the job done, right? Am I right?\n\nProbably.\n\nHave some ice cream.", sourceObjectiveStatus = "unverified-source-field" }
quests[25729] = { id = 25729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzo the Traitor", description = "<The Gnomecorder comes to life with a loud buzz.>\n\nCome in, {name}! Are you zhere? I have noted on ze map that you are near ze Cragpool Lake vater vheel, is that correct?\n\nIt vould appear that ze Venture Co. has holed up at ze vheel. Have a look around vhile you are up zhere. If you happen to zee a traitorous gnome by ze name of Gerenzo Wrenchwhistle, put your boot firmly up his keester for me and for Gnomeregan! I vill pay handsomely!", sourceObjective = "Kill Gerenzo Wrenchwhistle.", completion = "<The Gnomecorder buzzes loudly.>\n\nVonderful! That's von more name I can scratch off of my list!\n\nI vill be in touch.\n\nXakxak, out!", sourceObjectiveStatus = "unverified-source-field" }
quests[25730] = { id = 25730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BEWARE OF CRAGJAW!", description = "By order of people not wanting to get themselves devoured whole by a really huge fish, Cragpool Lake is OFF-LIMITS! Someone decided to up and put a huge, dwarf-eating fish in the lake.\n\nIt is strongly recommended that you stay out, however, if you are the heroic type and have a few friends around, do us all a favor and kill the damned thing! Maybe I can get some fishing done then, eh?\n\nIf you manage to actually do it, meet me back at Windshear Hold for a reward.\n\n-Ol' Irongoat", sourceObjective = "Kill Cragjaw and take Cragjaw's Huge Tooth.", progress = "You kill the beast?", completion = "Well I'll be a monkey's uncle. You actually got the beast, eh? Well, a deal's a deal! Here's your reward!", sourceObjectiveStatus = "unverified-source-field" }
quests[25731] = { id = 25731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bird in Hand", description = "It's time to get to the bottom of this. We need to interrogate the matron of these beasts, Marion Wormwing. We'll capture her alive. Here's the plan:\n\nThe harpies communicate across the ridge using a series of signal fires. If we extinguish one, Marion is sure to come investigate.\n\nYou fight her as a distraction while I sneak up behind and grab her. I'll leave the questioning to you. Let's get her, {name}!", sourceObjective = "Extinguish a Harpy Signal Fire to get the attention of Marion Wormwing. Fight her until Thisalee subdues her, then question the harpy matron.", progress = "Marion used to visit the shrine here. Skylord Omnuron tried to give the harpies the benefit of the doubt, but I never trusted her.", completion = "So the harpies are tools of some sort of dragon - \"Sethria.\"\n\nBut what are the dragons doing to those eggs? And what's this 'special' egg that Sethria wanted so badly?\n\nThis is beyond me, {name}. I've given a report to Skylord Omnuron - he'll know what to do next.", sourceObjectiveStatus = "unverified-source-field" }
quests[25732] = { id = 25732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bone to Pick", description = "We did it!\n\nGnaws is down, and I have our shiney!\n\nThat's good news.\n\nDarn shiney is cursed treasure - makes everyone who touches it a skeleton.\n\nThat's bad news.\n\nThese cursed pirates say the Gilblin King has the secret to remove the hex.\n\nThat's good news.\n\nI can't step foot outside the reef or I'll be cursed forever.\n\nThat's bad news.", sourceObjective = "Budd wants you to collect the Pewter Pounder from King Gurboggle at Gurboggle's Ledge.", progress = "So, {race}...\n\nYou gunna remove this curse, or what?", completion = "This is it?\n\nHow is this gunna remove - wait a minute...", sourceObjectiveStatus = "unverified-source-field" }
quests[25733] = { id = 25733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Out Of Here, Stalkers", description = "Thelgen Rock's an important site here. We need to use it to study the bedrock formations an' such.\n\nOf course, it can't be that easy, so Thelgen Rock's also full of giant cave stalkers. Big as a dwarf and twice as hungry. Like I said, these fancy-lads are researchers, not warriors, so if I want them to get anything done you're gonna have to help me clear the filthy bugs out.\n\nKill as many of the blighters as you can and I'll make it worth your while, {name}.", sourceObjective = "Kill 7 Cave Stalkers and 7 Leech Stalkers.", completion = "Good job. I wouldn't be surprised if the horrid things had eggs in there somewhere, but it'll do for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25734] = { id = 25734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down In Thelgen Rock", description = "I'm feeling slightly less wobbly now, so I'm going to start setting up the level for my final measurements here. There's one last thing I need from you.\n\nThere's a seismograph set up deep within Thelgen Rock to record any movements in the earth. If things have been continuing to shift since the cataclysm, this'll tell us.\n\nThe seismograph's at the very bottom of the cave; find it and bring the record it's created back to me.", sourceObjective = "Retrieve the Thelgen Seismic Record from Thelgen Rock.", progress = "Let's see what we've got, aye?", completion = "Wonderful, lad. This should be all we need. Let's have a look.", sourceObjectiveStatus = "unverified-source-field" }
quests[25735] = { id = 25735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incendicite Ore", description = "Thelgen Rock over yonder is something of a natural wonder. It's the only known source of incendicite in the world!\n\nThe stuff's rare, highly sought, and ridiculously explosive. Hit it with a steel mining pick and you'll set off a fireworks show that'll put a room full of goblins to shame.\n\nLuckily, I've developed a spark-proof pick for such tasks. I'll loan it to you if you bring me back some incendicite ore, and I'll split you in on the profits, of course.", sourceObjective = "Collect 8 pieces of Incendicite Ore.", progress = "Well, you look like you're in one piece.", completion = "Glorious! Beautiful stuff, this ore.\n\nGood on you for not droppin' your pick. Last person I sent out let the butt end hit the floor, and that part's not sparkproof.", sourceObjectiveStatus = "unverified-source-field" }
quests[25736] = { id = 25736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Floodsurge Core", description = "This is all that's left of the huge elemental that attacked you: a frothing orb of water that continues to fight your grip.\n\nForba might appreciate seeing proof that you helped stop another threat to the camp.", sourceObjective = "Deliver the Floodsurge Core to Forba Slabchisel.", progress = "Eh? What's that you've got there?", completion = "The thing's still got some fight in it! Amazing!\n\nYou're a tough one, {name}. It's much appreciated. I'd say a reward is in order before you head out.\n\nKeep doin' your best for Ironforge, you hear? And if you ever see my sister, say hello for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25737] = { id = 25737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenuous Negotiations", description = "From what I've learned about these water-goblins, this should work.\n\nI've crafted a shark-tooth necklace from the items you scrounged up. Not only is it a shiny trinket, but it's a memento of Gnaws' death. There's no telling how many gilblins were eaten alive by that monster.\n\nOffer the necklace to the gilblin leader. In exchange, I need an artifact called The Pewter Pounder.\n\nAnd be quick about it, kid. I'm already beginning to miss my flesh...", sourceObjective = "Speak to King Gurboggle.", sourceObjectiveStatus = "unverified-source-field" }
quests[25739] = { id = 25739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If the Horde Don't Get You...", description = "<Captain Kosak coughs weakly.>\n\nWas traveling up Webwinder Path, coming from Northwatch Expedition Base Camp in the south. Ambushed. Not by Horde. Spiders. Big, ugly, hairy, nasty spiders.\n\nFought off dozens, maybe hundreds. Lost count. Overtaken by their queen. She took a chunk right out of me. Barely made it out alive. Might be dying.\n\nMore of my men coming. Must provide safe passage. Kill spider queen.\n\n<Captain Kosak passes out.>", sourceObjective = "Kill Queen Silith.", completion = "<Captain Kosak forces a smile at you.>\n\nDon't worry about me. Should be ok now that big hero killed the spider queen.\n\nCan get reinforcements through safely now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25740] = { id = 25740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fact-Finding Mission", description = "The dragon Sethria must be stopped. We know that her roost is south of here, along the southern cliffs of Hyjal, but beyond that we know little else.\n\nI have sent Thisalee on a fact-finding mission to Sethria's Roost. She specifically requested your help - evidently you made quite an impression with the young druid.\n\nMeet Thisalee just beyond the tunnel leading to Sethria's Roost. And remember, this is a fact-finding mission - don't do anything crazy!", sourceObjective = "Report to Thisalee at the entrance to Sethria's Roost in Mount Hyjal.", completion = "Ah, {name}! I was hoping to see you out here.\n\nWhat, Omnuron calls this a 'fact-finding mission?' Bah! Facts are best found on corpses.\n\nLet's do some damage.", sourceObjectiveStatus = "unverified-source-field" }
quests[25741] = { id = 25741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for the Future", description = "Poisoned travelers are becoming a common occurrence around Windshear Hold. Why just the other day a Northwatch Captain fell prey to the spiders of the Webwinder Hollow. He would have died to the poison had it not been for my anti-venom. Sadly my stock of anti-venom is almost completely depleted.\n\nIf you're heading south towards Webwinder Hollow, would you kindly recover Deepmoss venom sacs for me? You should be able to acquire them from Deepmoss spiders.", sourceObjective = "Collect 10 Deepmoss Venom Sacs.", progress = "Have you recovered the venom sacs I requested?", completion = "This will keep us stocked on anti-venom for the foreseeable future. Thank you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25743] = { id = 25743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decisions, Decisions", description = "This is no magic solution to my curse! It's just a hammer!\n\nI may be crazy, but I'm not stupid.\n\nThere's NO WAY I'm gunna use this to break my shiney - not after all I've gone through to get it.\n\n<Budd pauses in thought for a moment.>\n\nBut that means I'm stuck down here for eternity...\n\nI had just learned to sail, you know.\n\nOhhh... I can't decide.\n\nHere, you take the hammer and I'll just set the shiney down and look the other way.", sourceObjective = "You must use The Pewter Pounder to destroy The Pewter Prophet.", completion = "Oh, what might have been...", sourceObjectiveStatus = "unverified-source-field" }
quests[25744] = { id = 25744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negotiations", description = "{name}, great job defending the Speedbarge! I've got something else that I need you to help out with.\n\nI've sent Crazzle Sprysprocket and Kravel Koalbeard northeast to negotiate with the centaur survivors. Their Splithoof Heights is dripping with oil!\n\nI figure those smelly half horses won't know what they've got and we'll get the rights to pump up that black gold for a song, but I'd feel better if you took charge of the talks.\n\nWhat do you say?", sourceObjective = "Speak with Crazzle Sprysprocket at the Splithoof Heights in Thousand Needles.", completion = "<Crazzle gets a gleam in his eye.>\n\nI've got Kravel Koalbeard up there talking to one of their chiefs, but now that you're here, we'll have the rights to pump up their oil in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[25745] = { id = 25745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negotiations", description = "{name}, great job defending the Speedbarge! I've got something else that I need you to help out with.\n\nI've sent Riznek and Trackmaster Zherin northeast to negotiate with the centaur survivors. Their Splithoof Heights is dripping with oil!\n\nI figure those smelly half horses won't know what they've got and we'll get the rights to pump up that black gold for a song, but I'd feel better if you took charge of the talks.\n\nWhat do you say?", sourceObjective = "Speak with Riznek at the Splithoof Heights in Thousand Needles.", completion = "<Riznek gets a gleam in his eye.>\n\nI've got Trackmaster Zherin up there talking to one of their chiefs, but now that you're here, we'll have the rights to pump up their oil in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[25746] = { id = 25746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethria's Brood", description = "First order of business is to thin the herd here. This place crawls.\n\nLet's start slaughtering these dragonkin and worry about why they're here later.", sourceObjective = "Slay 12 of Sethria's Minions: Any combination of Twilight Dragonkin or Twilight Dragonkin Armorers.", progress = "Have you delivered a message?\n\nBe sure to take flight, too, and hunt Sethria's minions on the other ledges.", completion = "You're good at this.\n\nI like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25747] = { id = 25747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking Forward", description = "The Admiral used the information you gathered for him to make a forward post under the terrace to our west. He's been preparing there for some kind of attack against the naga.\n\nYou should go to him immediately and inform him of the scope of what you've witnessed. Our force is small, and I fear for our soldiers if we charge in too recklessly.\n\nTake my sea horse. It knows the way.", sourceObjective = "Find and speak to Admiral Dvorek under the southern terrace in the Ruins of Vashj'ir.\n\nUse Wavespeaker Valoren's sea horse to reach the forward post quickly.", completion = "Good to see you again, {class}. I almost thought we'd lost you to the Wavespeaker's fool errand.\n\nDid anything come of it?", sourceObjectiveStatus = "unverified-source-field" }
quests[25748] = { id = 25748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear Goals", description = "I see. The news you bring is grim, but I was not entirely unprepared for such possibilities. Without any effective scouting of naga numbers, I knew our plan was risky, but that's why we established this forward post.\n\nLet me put it to you plainly, {class}. If we do not keep the naga off-balance, they will bring the fight to us. We do not have the structures or the men to mount a defense, so that is not an option.\n\nWe need more time. Can you thin their numbers to the south?", sourceObjective = "Kill 10 of the naga forces building up on the ground level, under the southwestern terrace.", completion = "More naga are amassing to the south than reported too it seems. We shall have to move quickly then.", sourceObjectiveStatus = "unverified-source-field" }
quests[25749] = { id = 25749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Entirely Unprepared", description = "I overheard your conversation with the Admiral. I know what we're doing sounds insane, but we really don't have much choice. There are people back at that cave that are depending on us.\n\nI've stationed lookouts on various ledges in the immediate area. They're burning ammo fast on the scattered naga scouts. Can you bring them more crossbow bolts to buy us some extra time?", sourceObjective = "Deliver 8 Bundles of Crossbow Bolts to Alliance Lookouts positioned on ledges under the southern terrace.", completion = "You are perhaps the most dependable person I've ever met. I wish I could have more men half as thorough as you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25751] = { id = 25751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Properly Inspired", description = "Hello! I've been scrambling, scrambling to prepare for the Admiral's assault. He's got high hopes and high plans to blow all kinds of things sky high! ...or water high? That would do.\n\nBlowing things high takes EXPLOSIVES! I don't have explosives. It's saddening. Very saddening.\n\nI've been properly inspired to improvise though, and the solution has become apparent. The bulbs on the seaweed hanging from the ruins contain a surprisingly volatile gas. Maybe you might gather some for me? Pretty Please?", sourceObjective = "Gather 8 Bloated Kelp Bulbs hanging under the southwestern terrace.", progress = "Tick, tock, tick, tock. Always in such a hurry. No time for innovation. What I wouldn't give for a lab again!", completion = "You are brave indeed! I've seen you battling all manner of murloc, naga, and pointy-toothed fish, but that was nothing! The way you just sling those kelp bulbs under your arm like that is a whole new kind of fearless. BOOM! You could blow up at any second.\n\nYou're my kind of {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25752] = { id = 25752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Action", description = "We have everything we need to begin the attack.\n\nIf your claims were correct, you would do well to make sure you cling tight to your mount as we make the attack. Anyone who gets caught in the open water isn't likely to out-swim a naga.\n\nKill as many as you can as we make the attack run and we'll rendezvous on the broken ledge of the terrace above once we've expended our explosives. Hopefully by that point there will be few enough that we can finish them off the old-fashioned way.", sourceObjective = "Speak to Engineer Hexascrub just outside of the building to join the assault, then use your improvised explosives to kill 100 Azsh'ir Soldiers, 20 Azsh'ir Wave Screamers, and 12 Azsh'ir Archaens.", completion = "You did great up there! You devastated their ranks, but there were far more than we accounted for, and most of our men went down out there in the masses of naga.\n\nWe'll need to hold this position as long as possible to buy them time. Hopefully some of them will still make it to the rendezvous.", sourceObjectiveStatus = "unverified-source-field" }
quests[25753] = { id = 25753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen But Not Forgotten", description = "That was a disaster! Most of our men went down to spears before making it anywhere near the rendezvous.\n\nWe're only going to be able to hold this position for so long before the naga overrun us. We need to get out there to the southwest and save as many of the men as we can find - do anything you can.\n\nThey won't last long. Please hurry!", sourceObjective = "Rescue 6 Injured Assault Volunteers.", progress = "These guys aren't in good shape. We may need to retreat sooner than we'd like.", completion = "Thank you. Truly.\n\nWe need to get these men moving as soon as possible. I'll meet you back at the forward post soon, I'm sure.", sourceObjectiveStatus = "unverified-source-field" }
quests[25754] = { id = 25754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gauging Success", description = "Vicious louts... they did a lot of damage with those spears.\n\n<The admiral winces slightly as he clutches a wound on his side.>\n\nWe'll hold here as long as we can for all the men to make it. I need someone to scout their numbers to see how much damage we did.\n\nOne of the biggest groups of them was around the corner on the northwest portion of this round terrace, and the other was a bit farther to the north in the small tunnel, also on this middle level of the ruins.\n\nUp for some scouting?", sourceObjective = "Scout the northwestern portion of the circular terrace and the tunnel under the main stairs to the north. Both locations are on Nar'shola Terrace, the middle level of the ruins.", completion = "Still so many? They must want something very important here to come in such numbers.\n\nI will be honest with you, {name}, because you deserve at least that: I don't know how much hope there is. We will retreat shortly, but we won't be able to defend ourselves when they strike back. We don't have anywhere to run... we're running out of options.\n\nI'm sorry, I should keep such thoughts to myself. Do me a favor and don't mention any of that to the men. I'll figure something out.", sourceObjectiveStatus = "unverified-source-field" }
quests[25755] = { id = 25755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: The Slaughter of Biel'aran Ridge", description = "Look, I know this is asking a lot during a time like this, but I need you to tear yourself away from this defeat for a moment.\n\nI will tend to these soldiers - you need to find the location of that battle with the Kvaldir General to the west that you told me about. You should be able to glimpse more of the Battlemaiden's experiences from there. I have a strong feeling that the key to defeating these naga will lie with that Battlemaiden.\n\nPlease hurry - I will do everything I can to buy you time.", sourceObjective = "Witness the continuing story of the Battlemaiden by using her broken blade at the site of the Kvaldir General's death.", completion = "You're finished! Just in time. I don't think we could have held them much longer.\n\nAn artifact? Could this be something we can use against the naga? I suppose that would require finding it.\n\nWe may have to attend to more pressing matters first, until an opportunity to pursue this further presents itself.", sourceObjectiveStatus = "unverified-source-field" }
quests[25756] = { id = 25756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Zherin!", description = "If we're going to get those oil drilling rights, we need to know what the Horde is offering. How can we win if we can't do them one better?!\n\nTheir negotiator, Trackmaster Zherin, is up there talking with one of their khans right now. Why don't you head up and persuade him to hand over the Horde's proposal?\n\nYou don't have to kill him... we're not savages! Just rough him up a bit.", sourceObjective = "Obtain the Horde's Proposal.", progress = "Do you have the Horde's proposal? What are they offering for the drilling rights?", completion = "What?! How'd they get that much gold to offer?\n\nWe don't have that kind of money!", sourceObjectiveStatus = "unverified-source-field" }
quests[25757] = { id = 25757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Koalbeard!", description = "If we're going to get those oil drilling rights, we need to know what the Alliance is offering. How can we win if we can't do them one better?!\n\nTheir negotiator, Kravel Koalbeard, is up there talking with one of their khans right now. Why don't you head up and persuade him to hand over the Alliance's proposal?\n\nYou don't have to kill him... we're not savages! Just rough him up a bit.", sourceObjective = "Obtain the Alliance's Proposal.", progress = "Do you have the Alliance's proposal? What are they offering for the drilling rights?", completion = "What?! How'd they get that much gold to offer?\n\nWe don't have that kind of money!", sourceObjectiveStatus = "unverified-source-field" }
quests[25758] = { id = 25758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gap in Their Armor", description = "Do you see what they're doing here? They're affixing armored plates onto the Dragonkin. A page out of Deathwing's book, I suppose.\n\nThose Twilight Juggernauts look like they'll be invincible once they're complete. There's got to be a way around that armor plating!\n\nRun out there and fetch some of the Twilight armor plates that are waiting to be installed. We'll figure out how to beat this.", sourceObjective = "Gather 8 Twilight Armor Plates.", progress = "Did you get a hold of some plates? Did you have to kill anyone to get them?\n\nI hope so.", completion = "Look at these things. Ugh, the runes make my eyes hurt. This one here is meant to sear flesh? Seriously? Ouch! Wait a minute...\n\nThese plates are designed to be riveted directly into flesh. The pain must be unbearable!", sourceObjectiveStatus = "unverified-source-field" }
quests[25760] = { id = 25760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: The Invasion of Vashj'ir", description = "The shard you recovered looks to be of naga origin. I had hoped to find a strong focal object like this for a spell I've been working on that would allow us to glimpse into the recent past.\n\nI've enchanted the blade, but you'll have to take it to a place where we know its owner was. I want you to travel back to the site where you found it and use the blade.\n\nPerhaps we can uncover more behind what the naga are doing here. Or even better, maybe we'll uncover a weakness that will give us a better chance.", sourceObjective = "Use the Blade of the Naz'jar Battlemaiden at the battle site at the southeast end of the ruins.", completion = "A Battlemaiden? I never heard of such a thing.\n\nThe way you explain it, it sounds like the naga forces are far greater in scope than the Admiral could possibly have realized. We might be able to learn more through the blade if we can find other locations where this Battlemaiden was present, but the information you gave me makes me fear for the admiral and his soldiers. We must warn them.", sourceObjectiveStatus = "unverified-source-field" }
quests[25761] = { id = 25761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disassembly", description = "We have to stop these juggernauts before they're completely encased in armor. Right now they're vulnerable, but only if we pry aside the plates and hack at the marred flesh beneath.\n\nTake my shiv, and jam it between the plates of armored juggernauts to deprive them of their armor.\n\nOnce they break from their trance, you're in for a tough fight - keep prying loose that armor and stop those juggernauts!", sourceObjective = "Use Thisalee's Shiv to awaken and kill 3 Twilight Juggernauts. The shiv can be used multiple times to tear down a Juggernaut's armor.", progress = "Oh good.\n\nYou're still alive.", completion = "That was some fancy bladework, {name}!\n\nThere's one less threat for us to worry about in Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25762] = { id = 25762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Brazier", description = "What do we have here? A {race}? Come to steal our land with your honeyed tongue and promises?\n\nYou do not fool me. I have lived a long time, and I know what dealing with your kind means. But the khans do not listen to their elders like they used to.\n\nSince you are here, I will put you to use. When the waters rushed in, the great water spirit, Aquarian, doused the Ancient Brazier deep inside of Splithoof Hold.\n\nUse this brand to reignite the brazier. Aquarian is sure to come. Bring me the Sacred Flame.", sourceObjective = "Reignite the Ancient Brazier and obtain the Sacred Flame.", progress = "You have the Sacred Flame? Do not speak to me unless you do, {race}!", completion = "You did this favor to ingratiate yourself with me, but I will not sing your praises.\n\nI know what is to come. Where the sea failed, the great air spirit will strike you and your people down for your many transgressions against the elements.\n\nBegone from my sight!", sourceObjectiveStatus = "unverified-source-field" }
quests[25763] = { id = 25763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Codex of Shadows", description = "<This elaborate book contains hundreds of vellum pages bound within a slate cover. It's written in many languages, most unfamiliar. Carefully inked illustrations depict sorcerers or even entire buildings vanishing into curtains of shadow.>\n\n<Many illustrations depict magical artifices like those you see around camp. You suspect the dragon Sethria is trying to keep something hidden. Thisalee will want to hear about this!>", sourceObjective = "Report what you've discovered to Thisalee Crow at Sethria's Roost in Mount Hyjal.", completion = "They're doing what?\n\nThey're cloaking something? Of course - so our aerial scouts can't see anything with our eagle-eyes!", sourceObjectiveStatus = "unverified-source-field" }
quests[25764] = { id = 25764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Hunt", description = "Skylord Omnuron wants us to find Aviana's Egg, and I can almost guarantee you it's cloaked by one of Sethria's shadow devices.\n\nSearch around the camp for shadow cloak generators and shut those things down until you find the egg.\n\nOnce you've unveiled it, I'll call out to the other druids. Defend that egg until we can carry it off to safety.\n\nGo get that egg, {name}!", sourceObjective = "Disable the Shadow Cloak Generators until you unveil Aviana's Egg. Once the egg is unveiled, defend it until the Druids of the Talon can carry it to safety.", completion = "We did it, {name}! Aviana's Egg should soon be tucked safely in the boughs of her shrine.\n\nDo you think this means she'll really return to us?", sourceObjectiveStatus = "unverified-source-field" }
quests[25765] = { id = 25765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tell 'Em Koko Sent You", description = "Northwatch could really use a powerful {race} like you. We're taking a beating in the Southern Barrens and need your help! Are you interested in lending the Alliance a hand?\n\nThe bomb? Yea, it's a problem, but Stonetalon isn't exactly prime real estate. This place was a dump before the Horde sunk their claws into it!\n\nI'll leave the choice in your hands. If you want to help us out in the Barrens, take my horse, Blue Steel. He's grazing at the crossroads south of here. He'll get you past the orc blockade.", sourceObjective = "Report to Force Commander Valen at the Northwatch Expedition Base Camp in Stonetalon Mountains.", completion = "Kosak sent you, eh? Surprising. I thought for sure that he'd be dead by now.\n\nWell if you made it past the blockade then you definitely have something that we can use.\n\nNow, do you have any news of the Horde? What are they doing? Where are they going? Tell me everything.", sourceObjectiveStatus = "unverified-source-field" }
quests[25766] = { id = 25766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Legacy", description = "The rage of the elements has unearthed a hidden Highborne city in the heart of Stonetalon Mountains.\n\nDirectly southwest of here, through Sishir Canyon, you will find the Ruins of Eldre'thar. Within the ruins lie treasures untouched by mortals for ten thousand years!\n\nTake this device and use it on the Highborne ghosts that inhabit the ruins. It will... put their souls to rest and also collect valuable data which I may peruse at a later date.", sourceObjective = "Use the Highborne Prison to bind 5 Highborne Spirits.", completion = "I assure you, simpleton, the spirits you captured are at rest. Do not let their protests move you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25767] = { id = 25767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capturing Memories", description = "The great cataclysm has unearthed a forgotten Highborne city within Stonetalon Mountains. You must venture southwest to the Ruins of Eldre'thar. Once you are there, search the area for ancient relics. Return the relics to me so that I may study them, {name}.\n\nGo! Lest we keep the arcanist waiting!", sourceObjective = "Collect 8 Eldre'thar Relics.", progress = "Have you recovered the ancient relics?", completion = "Wonderful! Arcanist Valdurian will be most pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[25768] = { id = 25768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombs Away: Mirkfallon Post!", description = "Scout Commander Barus, stationed at Mirkfallon Post, to the northwest, has spotted the Horde bomb. The Krom'gar hot air balloon, with bomb attached, is currently at the new goblin fueling station at Mirkfallon Lake. This might be the opportunity we need to take that thing out once and for all.\n\nGather your things, {name}, and move out! Scout Commander Barus awaits your arrival at Mirkfallon Post.\n\nAnd {name}, your tenacity is a testament to the strength and fortitude of the Alliance!\n\nGlory be unto you!", sourceObjective = "Report to Scout Commander Barus at Mirkfallon Post in Stonetalon Mountains.", completion = "I'm assuming you saw the Krom'gar hot air balloon on your way here. If not, get your eyes checked. It's hovering directly over the oil platform.", sourceObjectiveStatus = "unverified-source-field" }
quests[25769] = { id = 25769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallowmere Beckons", description = "You're still here? What are you waiting for, a personal engraved invitation? Lord Fallowmere beckons, fool! Go to him now!", sourceObjective = "Speak to Lord Fallowmere at Windshear Hold in Stonetalon Mountains.", completion = "Good to see you again, {name}. I have some news from Mirkfallon Lake.", sourceObjectiveStatus = "unverified-source-field" }
quests[25770] = { id = 25770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keg Run", description = "Alright. We need to get this ale to where it's going right away!\n\nIronforge has sent out an expedition of surveyors to check the damage done to the wetlands when the dam burst. Forba Slabchisel's the one leading it...and believe me, you don't want to get on her bad side!\n\nShowing up with an armful of ale will help with that. Go and take this ahead to her, and she might even ask you to stick around for some work.", sourceObjective = "Deliver the Mountaineer's Ale to Forba Slabchisel at Slabchisel's Survey.", progress = "Aye? What've you got for me there?", completion = "Hah! Nice to see those addlebrained mountaineers knew to hand the ale off to a real man to get the job done.\n\nWelcome to my survey. If you're of the mind to help Ironforge by takin' over the intended jobs of some useless, lazy sods that call themselves dwarves, you're in the right place!", sourceObjectiveStatus = "unverified-source-field" }
quests[25771] = { id = 25771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Draenei's Junk...", description = "A shard of glimmering rock sits before you.  You sense that this item would be of value to someone within the Blasted Lands.", sourceObjective = "Return the Imperfect Draenethyst Fragment to Kum'isha the Collector in Blasted Lands.", progress = "Well? Draenethyst?", completion = "Just a shard?  Pfuh!  This gets me nothing!  Take your reward and get out of my sight.\n\nSounds familiar?  It should, because I say it a thousand times per day.\n\nOh how I loathe this world.", sourceObjectiveStatus = "unverified-source-field" }
quests[25772] = { id = 25772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kum'isha's Endeavors", description = "A glimmering sphere sits before you.  You sense that this item would be of great value to someone within the Blasted Lands.", sourceObjective = "Bring the Flawless Draenethyst Sphere to Kum'isha the Collector in Blasted Lands.", progress = "Have you found a flawless draenethyst sphere?", completion = "Simply amazing.  I had doubted that anyone could find another sphere, yet here it is, pulsating in my hands.\n\nWell done, {name}!\n\nShould you find anymore--and I believe this to be an impossibility--return them to me and I shall reward you again.", sourceObjectiveStatus = "unverified-source-field" }
quests[25773] = { id = 25773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Natural Occurrence", description = "This shard is all that is left from the rift that stood here before.  The connection between the shard and the rift is unknown, but perhaps someone more versed in the elements would know more.\n\nSeek out an Earthen Ring Emissary at any capital city.  This could be exactly what they are looking for.", sourceObjective = "Take the Elemental Shard to an Earthen Ring Emissary in Ironforge, Stormwind, Exodar or Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[25774] = { id = 25774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fool's Gold", description = "We definitely DO NOT have the kind of gold that the Horde is offering. {name}, we have to do something or we're not going to be able to get those drilling rights!\n\nWait a minute! There was this report from an underwater survey that we did right after the Cataclysm struck. Something about some gold-looking ore that was pushed up from underground. That's it!\n\nHead west to the old stomping grounds of the centaur, Splithoof Crag and Splithoof Hold, and dig some up.", sourceObjective = "Collect 8 Needles Pyrite Ore Chunks.", progress = "Once you return with enough of that pyrite, we'll give it a once over with a paint brush, pile it all up on a pallet, and send you back up with it to the chieftain.", completion = "Genius! Now, where's that gold paint? I know it's around here somewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[25775] = { id = 25775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fool's Gold", description = "We definitely DO NOT have the kind of gold that the Alliance is offering. {name}, we have to do something or we're not going to be able to get those drilling rights!\n\nWait a minute! There was this report from an underwater survey that we did right after the Cataclysm struck. Something about some gold-looking ore that was pushed up from underground. That's it!\n\nHead west to the old stomping grounds of the centaur, Splithoof Crag and Splithoof Hold, and dig some up.", sourceObjective = "Collect 8 Needles Pyrite Ore Chunks.", progress = "Once you return with enough of that pyrite, we'll give it a once over with a paint brush, pile it all up on a pallet, and send you back up with it to the chieftain.", completion = "Genius! Now, where's that gold paint? I know it's around here somewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[25776] = { id = 25776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethria's Demise", description = "While you've been raiding Sethria's nest, messages have been flying back and forth between here and the shrine. Skylord Omnuron was at first reluctant, but I've persuaded my fellow druids to risk a direct assault on Sethria herself.\n\nEveryone agreed to my plan... provided YOU spearhead the attack.\n\nTake this signal rocket and engage Sethria on the far ridge. When she reveals her true colors and shifts to her dragon form, fire the rocket and backup will arrive to help you!", sourceObjective = "Slay the dragon Sethria. Once she reveals her true form, you will need to use the signal rocket to call in reinforcements!", progress = "If a minor dragon like Sethria can cause us so many problems, I hate to see what else Twilight's Hammer has in store...", completion = "Sethria is slain! I knew it was worth the risk.\n\nI'll stay here to look for survivors, but I imagine they'll want to see you back at the shrine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25777] = { id = 25777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onwards to Menethil", description = "This news needs to get to Menethil as soon as possible. I'll send you along on my fastest ram, {name}.\n\nHe knows the way, just make sure you're steady in the saddle and hold on tight.\n\nDon't dawdle around the camp. We've got to send word quickly!", sourceObjective = "Deliver the Slabchisel Report to Captain Stoutfist in Menethil Harbor.", progress = "Welcome to Menethil, stranger. I hope you've got good news or a stiff drink with you.", completion = "Let's take a look here.\n\nOh, this is just lovely. \"Significant geological instabilities\"? \"Threat of sudden, massive topological destabilization\"?\n\nNice to hear that somethin' bad might happen around here. I guess we'll just pick up our flooded town and fly it off somewhere safe!\n\nBah!", sourceObjectiveStatus = "unverified-source-field" }
quests[25778] = { id = 25778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fake Gold for Black Gold", description = "Now that the \"gold\" is ready, I want you to take it up to Khan Ablinh. He'll be so overwhelmed, I bet he'll offer to help us setup the drilling rigs. We could use the horsepower.\n\nHaha, get it? Horsepower?", sourceObjective = "Deliver the Pallet of \"Gold\" to Khan Ablinh at the Splithoof Heights in Thousand Needles.", progress = "What's this? That is a lot of gold you have there.", completion = "Just put it down on the ground, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25779] = { id = 25779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fake Gold for Black Gold", description = "Now that the \"gold\" is ready, I want you to take it up to Khan Blizh. He'll be so overwhelmed, I bet he'll offer to help us setup the drilling rigs. We could use the horsepower.\n\nHaha, get it? Horsepower?", sourceObjective = "Deliver the Pallet of \"Gold\" to Khan Blizh at the Splithoof Heights in Thousand Needles.", progress = "What's this? That is a lot of gold you have there.", completion = "Just put it down on the ground, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25780] = { id = 25780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Menethil Keep", description = "We'd barely pulled ourselves together after the flood when the Dark Iron hit the town. My men and I all rushed to defend the townsfolk, but the crazed fools retreated right into the keep itself.\n\nThey're holed up good, and we can't destroy the keep. Not with half the town in ruins already.\n\nTake my place, {name}. I'd take the leader on myself if he hadn't dealt me this blow. Enter the keep, slay Horghast, and bring this to an end!", sourceObjective = "Kill Horghast Flarecrazed.", completion = "He's dead! Thank the Makers...\n\nI don't like the looks of them, lad. The Dark Iron I've tussled with were never this crazy. Something's getting to these sods...", sourceObjectiveStatus = "unverified-source-field" }
quests[25790] = { id = 25790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Crazzle", description = "I am NOT stupid!\n\nGo back to your master and tell him that there will be NO deal! That is, if you can survive to make it back to him.", sourceObjective = "Speak with Crazzle Sprysprocket at the Splithoof Heights in Thousand Needles.", completion = "THEY WHAT?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25791] = { id = 25791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Riznek", description = "I am NOT stupid!\n\nGo back to your master and tell him that there will be NO deal! That is, if you can survive to make it back to him.", sourceObjective = "Speak with Riznek at the Splithoof Heights in Thousand Needles.", completion = "THEY WHAT?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25792] = { id = 25792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushing Forward", description = "Most of the mountaineers and steam tanks in Dun Morogh are battling along the Frostmane Front, which is approaching us from the southeast. We can barely hold the trolls back, let alone advance into their village and take on their leader.\n\nThey've blocked our path of approach with mysterious totems that choke mountaineers who come in range, leaving the victims helpless against their enemies. This stone is inscribed with a rune of fire; it should be able to destroy the totems and free our mountaineers.", sourceObjective = "Use the Rune of Fire to destroy 4 Constriction Totems in the Frostmane Front.", progress = "Was the rune able to destroy the totems? Were we too late?", completion = "Finally, some good news from the Frostmane Front. I'll have the mountaineers press their attack immediately. Now, we must signal our gnomish allies at Steelgrill to start their advance.", sourceObjectiveStatus = "unverified-source-field" }
quests[25793] = { id = 25793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deep Reaches", description = "The purpose of this base was to establish a foothold in Stonetalon for Theramore and to open up a supply line to the night elves. The Horde, unfortunately, has given us one hell of a fight. Hellscream's armies are mighty and unrelenting. I haven't seen this type of ferocity from the Horde since the second war.\n\nNow it would appear that the mine the Explorers' League dug out is being used by the Horde to \"backdoor\" us. We need to seal that thing off!", sourceObjective = "Speak to Steeltoe McGee at the Deep Reaches in Stonetalon Mountains.", completion = "Seal it off? That's gonna take some work, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[25794] = { id = 25794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undersea Sanctuary", description = "I believe I've located the author of your note, friend.\n\nIt would seem that he is in desperate need of attention if he is to survive.\n\nI shall attune one of my scrying orbs, that you might see him for yourself.", sourceObjective = "Use Erunak's Scrying Orb to view the location of Deepmist Grotto.", progress = "Have you familiarized yourself with the cavern's location, {name}?", completion = "We must make haste!\n\nAs you can surely see, his time is not long.", sourceObjectiveStatus = "unverified-source-field" }
quests[25795] = { id = 25795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Shrine", description = "Aviana's Egg should have arrived safely back at the Shrine. You should go check on it! Choluna should know how to handle this.\n\nI'll finish the last of our business here and catch up with you later.", sourceObjective = "Return to Choluna at the Shrine of Aviana in Mount Hyjal.", completion = "{name}! Is it true you led an assault against a twilight dragon?\n\nYou are truly a herald of the ancients!", sourceObjectiveStatus = "unverified-source-field" }
quests[25796] = { id = 25796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eminent Domain", description = "It is our destiny to take this oil. Unfortunate that the centaur retreated to here when the sea rushed in.\n\nUnfortunate for them, that is.\n\nThey've spit in our faces, {name}. We made them a generous offer and they made the mistake of not accepting. Now we... you, will show them the error of their ways.\n\nClear the centaur off of the Splithoof Heights. The oil must flow!", sourceObjective = "Slay 15 Splithoof Heights centaurs.", completion = "That'll teach them. You've softened the Splithoof up enough that we should be able to govern them now with a minimal guard presence from the Speedbarge.\n\nThat is, once we've dealt with their supposed air elemental leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[25797] = { id = 25797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eminent Domain", description = "It is our destiny to take this oil. Unfortunate that the centaur retreated to here when the sea rushed in.\n\nUnfortunate for them, that is.\n\nThey've spit in our faces, {name}. We made them a generous offer and they made the mistake of not accepting. Now we... you, will show them the error of their ways.\n\nClear the centaur off of the Splithoof Heights. The oil must flow!", sourceObjective = "Slay 15 Splithoof Heights centaurs.", completion = "That'll teach them. You've softened the Splithoof up enough that we should be able to govern them now with a minimal guard presence from the Speedbarge.\n\nThat is, once we've dealt with their supposed air elemental leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[25798] = { id = 25798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Drill", description = "I'm not leaving here empty-handed! Are you?\n\nI bet you were wondering what's in the giant crate. Well, wait no longer. I want you to take one of our drilling rigs to the oil pools and pump us up some crude.\n\nOf course, you should expect the centaurs to attack. Just defend the drill long enough for us to get a barrel or two out of the ground.", sourceObjective = "Defend the Oil Drilling Rig.", completion = "Oil! Black gold! Tanaris Tea!\n\nWe're rich! We just have to clear out the remaining pesky centaur. I'm sure with all the money we're going to make, we can relocate them to some other bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[25799] = { id = 25799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Drill", description = "I'm not leaving here empty-handed! Are you?\n\nI bet you were wondering what's in the giant crate. Well, wait no longer. I want you to take one of our drilling rigs to the oil pools and pump us up some crude.\n\nOf course, you should expect the centaurs to attack. Just defend the drill long enough for us to get a barrel or two out of the ground.", sourceObjective = "Defend the Oil Drilling Rig.", completion = "Oil! Black gold! Tanaris Tea!\n\nWe're rich! We just have to clear out the remaining pesky centaur. I'm sure with all the money we're going to make, we can relocate them to some other bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[25800] = { id = 25800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Life Gives You Crabs", description = "There's a lot to do here, {class}, but we need to keep an eye out for the gifts of fate.\n\nWhen the flood rolled in, right over our houses, it swept a good number of ocean dwellers with it. Menethil Bay's full of crabs now, large and ripe for the picking.\n\nWhen life gives you crabs, go crab fishing, I say. Bring me back the largest, meatiest claws you can find and I'll pay you.", sourceObjective = "Collect 5 Meaty Crawler Claws from Harbor Crawlers.", progress = "Don't bother with the smaller claws, they're more work to shell than the meat's worth.", completion = "A hearty seafood dinner will lift everyone's spirits and help us get the town back in shape again. Thanks for the help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25801] = { id = 25801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claws from the Deep", description = "Murlocs are crawling out from the deep waters and building their villages on the coastline.  They are harassing our fishers and merchants and must be stopped.\n\nOne of these murlocs, Gobbler, skulks with other bluegill murlocs and harries merchants along the road, always then retreating to the safety of the nearby murloc hovels.  Our merchants are in jeopardy, and we will pay to secure them.\n\nGobbler prowls the river inlet north of here.  Find him, slay his kin, and bring me his head.", sourceObjective = "Collect Gobbler's Head from Gobbler and slay 12 Bluegill Murlocs of any kind.", progress = "Our merchants will not be safe until we are rid of Gobbler and those murlocs.", completion = "Ah, well done {name}.\n\nAccept this as payment for fulfillment of your contract with the Merchant Marines.", sourceObjectiveStatus = "unverified-source-field" }
quests[25802] = { id = 25802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Goods", description = "Not long ago a merchant vessel, the Blind Princess, was raided by murlocs.  Although the ship escaped intact, much of its cargo was dragged overboard by the creatures, including a very valuable statuette of Terenas Menethil.  We want that statuette recovered.\n\nSearch the coastal murloc hovels for crates, barrels and other evidence of lost cargo.  Find the Menethil statuette and return it to me.", sourceObjective = "Search the crates and barrels at the coastal Murloc camps.", completion = "This crate is covered with clawed scratches, and the marks of water damage.  Prying it open reveals soggy and rotted straw, as if something of value was stored in the crate.  You search through the straw...\n\n...and find an armload of red-colored bottles.", sourceObjectiveStatus = "unverified-source-field" }
quests[25803] = { id = 25803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search Continues", description = "You thoroughly search this cluster of murloc hovels, and find no trace of the Menethil statuette.\n\nPerhaps one of the two nearby hovels to the north and northeast will have more clues.", sourceObjective = "Search for the Menethil Statuette.", completion = "This barrel is largely untouched.  Prying it open...\n\n...you are assaulted by the pungent odor of cheese.  It's a little wet, but still tasty!", sourceObjectiveStatus = "unverified-source-field" }
quests[25804] = { id = 25804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search More Hovels", description = "This grouping of murloc hovels, after a thorough inspection, reveals nothing.\n\n...but you're certain that the next clue you find will be fruitful.\n\nOne of the hovels to the north must have the Menethil statuette!", sourceObjective = "Continue searching the Murloc hovels for the Menethil Statuette.", completion = "This barrel is halfway buried amidst the mud and grass ...", sourceObjectiveStatus = "unverified-source-field" }
quests[25805] = { id = 25805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return the Statuette", description = "After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw.  It depicts a young, long-haired paladin with hammer upraised.\n\nThis must be the Menethil statuette!  You must now return it to Karl Boran in Menethil Harbor.", sourceObjective = "Bring Karl Boran at Menethil Harbor in Wetlands the Menethil Statuette.", progress = "Do you have the statuette?", completion = "The captain of the Blind Princess will be relieved to hear this precious cargo has been recovered.  You've well earned this payment for services rendered.\n\nIt's good to see dependable folk like you, especially in trying times such as these.", sourceObjectiveStatus = "unverified-source-field" }
quests[25806] = { id = 25806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Put the Assass in... Never Mind", description = "Ah, the Explorers' League - such a profound group of morons. Not only do we have tauren ghosts up our butts, the Explorers' League has also managed to open up a backdoor to the primary Horde base in Stonetalon, Krom'gar Fortress.\n\nNow we've got Krom'gar assassins silently executing everyone in the mine.\n\nI need you to head in there and clean house.\n\nI almost forgot to give you these goggles. Put them on immediately. They'll make all the stealthed assassins in the mine plainly visible.", sourceObjective = "Kill 12 Krom'gar Assassins.", sourceObjectiveStatus = "unverified-source-field" }
quests[25807] = { id = 25807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Reborn", description = "I'm convinced that YOU are the herald of Aviana, {name}. It was you who first saw her and rescued her essence from the claws of a dragon.\n\nYes, I believe Aviana is to be reborn into our world. And you shall have the honor of ushering her over the threshold.\n\nTake this incense and burn it before Aviana's egg in the room just above me.\n\nThe ancient awaits, {name}. Our deliverance is here!", sourceObjective = "Use the Herald's Incense before Aviana's Egg at the Shrine of Aviana.", completion = "I ... live.\n\nThose that tried to corrupt me and kidnap my children will soon feel the rake of my talons, {class}. Believe it.\n\nContinue to push forward across Hyjal. I will collect myself and assemble with the other ancients.", sourceObjectiveStatus = "unverified-source-field" }
quests[25808] = { id = 25808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is This Thing On?", description = "<The Gnomecorder crackles with energy. You can hear Lieutenant Paulson on the other end.>\n\nStupid gnome junk... Is ANYBODY there? {name}, are you there?\n\nMaybe <he's/she's> dead.\n\nListen, if you can still hear me, we just got word that a Horde master assassin is in the mines, directing the other assassins. Find her, kill her, report back to me.\n\nPaulson, out.", sourceObjective = "Kill Master Assassin Kel'istra.", progress = "Oh so you are alive.", completion = "Nicely done, {name}! You worked the mines like a pro. Now how about returning my goggles.", sourceObjectiveStatus = "unverified-source-field" }
quests[25809] = { id = 25809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Man Behind!", description = "Horde monsters!\n\n<Corporal Wocard spits.>\n\nLook at this place! They've wiped out innocents! Civilians!\n\nListen, {name}, you've got to help us. Go into the Deep Reaches and look for surviving miners. If any are still alive they're probably scared witless! Check in the nooks and crannies of the mine. Maybe in mine carts! There are bound to be some left alive and in hiding.", sourceObjective = "Rescue 8 Frightened Miners.", completion = "Thank the Light! You truly are a righteous instrument of power! The Alliance is lucky to you have, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25810] = { id = 25810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hatchery Must Burn", description = "{name}! Choluna spoke true: the goddess has returned! A miracle in our midst.\n\nWhile you were able to kill the twilight dragon Sethria, we have not yet located all of the eggs that the harpies had delivered to her. Thisalee and I have tracked them to a great hatchery constructed within the Firelands. It is not of this realm, so Aviana cannot accompany you.\n\nFly south and enter the flamegate in the center of the valley. Farden Talonshrike has been sent ahead and will be waiting for you within.", sourceObjective = "Travel through the flamegate in the center of the Flamewake in Mount Hyjal. Speak with Farden Talonshrike once you are inside.", completion = "So it's true - Aviana has returned, with you as her herald.\n\nThere's much to be done here. We are deep in the heart of the Firelands. Sethria smuggled stolen eggs from Mount Hyjal here to hatch her own hideous creations - birds of prey, trained for war.\n\nI hope you're ready to fight back!", sourceObjectiveStatus = "unverified-source-field" }
quests[25811] = { id = 25811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shuttin Her Down", description = "To bring this mine down you're gonna need to blow up her support beams. I can provide you with the explosives you'll need, but you're gonna have to trudge through Krom'gar assassins to get to all of the beams.\n\nThe good news, if any exists, is that we always mark our support beams with a big 'X.' Look for the markers and plant this dynamite near 'em. Once you've planted all the dynamite come on back up here and I'll activate the explosives.\n\nKaboom!", sourceObjective = "Plant the Dynamite Bundle at the First Beam, Second Beam, Third Beam and Fourth Beam.", completion = "Here goes nothin'!", sourceObjectiveStatus = "unverified-source-field" }
quests[25812] = { id = 25812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spelunking", description = "Hurry, {name}!\n\nMake your way to that cavern at once.\n\nWe shall go behind you to ensure that you are not followed.", sourceObjective = "Speak to Private Pollard in Deepmist Grotto.", completion = "A... a {race}? Here?\n\nI must be mad...", sourceObjectiveStatus = "unverified-source-field" }
quests[25813] = { id = 25813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Blow that Horn", description = "That old, bitter centaur, Skycaller Vrakthris, mentioned a great air spirit that the centaur worship. To secure the Heights, the last step is for us to deal with this thing.\n\nI've seen them blow the giant horn at the top of the hill up there and an air elemental came down. It gave them orders and then dissipated.\n\nGo blow that horn, {name}.", sourceObjective = "Slay Whrrrl.", completion = "Well then, let's see them get any kind of magical hocus pocus air support now when we take over!", sourceObjectiveStatus = "unverified-source-field" }
quests[25814] = { id = 25814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Blow that Horn", description = "That old, bitter centaur, Skycaller Vrakthris, mentioned a great air spirit that the centaur worship. To secure the Heights, the last step is for us to deal with this thing.\n\nI've seen them blow the giant horn at the top of the hill up there and an air elemental came down. It gave them orders and then dissipated.\n\nGo blow that horn, {name}.", sourceObjective = "Slay Whrrrl.", completion = "Well then, let's see them get any kind of magical hocus pocus air support now when we take over!", sourceObjectiveStatus = "unverified-source-field" }
quests[25815] = { id = 25815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Third Fleet", description = "I was once First Mate on the Wave Mistress, ship-of-the-line in the Kul Tiras Third Fleet.  The Doomed Fleet.  Doomed, for on its last voyage the fleet was attacked by red dragons.  Dragons controlled by orcs!\n\nWe didn't stand a chance against that dragonfire...and our fleet was burned and sunk off this here coast.  I'm the sole survivor of those poor vessels...\n\n...Bring me my mead, {class}. It's down in the cellar of the inn. As far away as I put it from me, I can't go without it in the end.", sourceObjective = "Obtain Fitzsimmons' Mead from the cellar of the inn in Menethil Harbor.", progress = "Oh, I'm so very thirsty!  Won't you buy a drink for this poor, pathetic fool?", completion = "Ah!  That hits the spot, and loosens the tongue.  Thanks, mate!", sourceObjectiveStatus = "unverified-source-field" }
quests[25816] = { id = 25816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed to Roam", description = "<Bolstered, Fitzsimmons continues his tale...>\n\nI am the sole survivor of the ill-fated Third Fleet of Kul Tiras, wrecked off the coast to the north. On one of our ships was hidden a great, and terrible treasure, and the eerie power of it keeps the souls of my brothers trapped within the ships' rotting hulls.\n\nI'm haunted by them day and night. First Mate Snellig calls for me! He's supposed to be dead! Please, {name}, look for him near the shipwrecks and just...tell him to leave me alone!", sourceObjective = "Talk to the ghost of First Mate Snellig.", completion = "Fitzsimmons sent you, didn't he? It's been so long...", sourceObjectiveStatus = "unverified-source-field" }
quests[25817] = { id = 25817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cursed Crew", description = "The sailors of the Third Fleet are damned, forever cursed to wander these shores in agony. Fitzsimmons' anguish is tied to us; so long as we suffer, there can be no rest for him, either.\n\nYou must end the suffering of my crewmates' spirits. Purge their ghosts from this plane, and return to me.", sourceObjective = "Kill 5 Cursed Sailors and 5 Cursed Marines in The Lost Fleet.", completion = "The cries of anguish have been stifled...but the source of the curse still lurks.", sourceObjectiveStatus = "unverified-source-field" }
quests[25818] = { id = 25818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifting the Curse", description = "To break the curse, there must be a reckoning. Captain Halyndor damned us all to covet a forbidden artifact; the Eye of Paleth. His spirit still covets it, standing guard over the strongbox of his old ship, the Intrepid.\n\nVanquish the soul of the one who cursed us so, {class}. Defeat the Captain, claim his key, and spirit the Eye of Paleth far from this place.", sourceObjective = "Get the Intrepid Strongbox Key from Captain Halyndor.", progress = "This chest is securely locked.", completion = "The key is rusted but it fits the lock neatly.", sourceObjectiveStatus = "unverified-source-field" }
quests[25819] = { id = 25819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Paleth", description = "Opening the chest reveals a blackened orb, pulsing with an eerie light. This must be the foul Eye of Paleth that damned these sailors' souls.\n\nSuch corruption should be purged. Perhaps a priest in Menethil Harbor could help you.", sourceObjective = "Bring the Cursed Eye of Paleth to Glorin Steelbrow at Menethil Harbor in Wetlands.", progress = "How can I help you, lad?", completion = "The Eye of Paleth? You say Fitzsimmons sent you out?\n\nBy the light...not again. Fitzsimmons is dead, lad. You've not the first to come to me like this, either.", sourceObjectiveStatus = "unverified-source-field" }
quests[25820] = { id = 25820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mother's Worries", description = "My son Gimlok's the light of my life. It warms my heart to see him playin' with the other children.\n\nI can't help but worry, though. There's sharks not but a few feet away in the bay. If it's deep enough for one to swim its way here...\n\nI can't bear it! Please, you're clearly one {race} that's seen tougher situations than us townsfolk. Would you get rid of those nasty sharks for me? At least a few?", sourceObjective = "Kill 10 Harbor Shredfins.", completion = "Oh, bless your heart, to do such a thing for a married woman like me. You're too kind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25821] = { id = 25821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Kind of Job", description = "You've done an admirable job down here, {name}. Force Commander Valen has taken notice and requested that you see him immediately. He's got a special mission lined up for you - one that'll hopefully put a cold stop on the Horde's incursion into Stonetalon.", sourceObjective = "Report to Force Commander Valen at Northwatch Expedition Base Camp in Stonetalon Mountains.", completion = "I knew that you'd be a special snowflake when I first set my eyes upon you, {name}. So special, in fact, that I'd trust no one else here with what I'm about to ask of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25822] = { id = 25822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armaments for War", description = "I am going to need to put you in harm's way once more, {name}. To the east you will find a mineral rich excavation site that was recently overrun by the Horde. At that site are crates of our weaponry, scattered about all over the place. The Horde has only recently taken over, so it is unlikely that they've found all of our supplies.\n\nGet in there and get our Grimtotem friends some weapons!", sourceObjective = "Collect 10 Alliance Weapon Crates.", progress = "Have you gathered the armaments of war?", completion = "This should be enough to supply a hundred Grimtotem! Now to present the weaponry to their chieftain.", sourceObjectiveStatus = "unverified-source-field" }
quests[25823] = { id = 25823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unrelenting Horde", description = "While it is of utmost importance that you secure weapon crates immediately, we need the Unearthed Grounds to the east clear of Horde. If we are to open a supply line for our Grimtotem allies, we're going to need full access to the dig site.\n\nKill all Horde that you come across at the Unearthed Grounds, {name}. For the glory of the Alliance!", sourceObjective = "Slay 12 Horde enemies at the Unearthed Grounds.", completion = "I will call for the infantry to move in and clear up whatever might be left over. If only we had ten-thousand more like you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25824] = { id = 25824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Debriefing", description = "This soldier was near death, but I fear we do not have the time to await his full recovery. He has information we desperately need to know.\n\nBe patient with him, but keep him talking until we've learned all that we can.\n\nWith luck we might discover just what we're up against...", sourceObjective = "Speak to Private Pollard and learn about his ordeal.", progress = "That's it, {race}.\n\nThat's all I know...", completion = "Well, it's not encouraging, but it's something...", sourceObjectiveStatus = "unverified-source-field" }
quests[25825] = { id = 25825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver the Goods", description = "Alright, {name}, I need you to get this oil back to Fizzle on the Speedbarge, and let him know the good news!", sourceObjective = "Deliver the Barrel of Oil to Fizzle Brassbolts on Fizzle & Pozzik's Speedbarge in Thousand Needles.", progress = "What's this? Is that oil?!", completion = "It is oil! You're really proving yourself to be invaluable, {name}!\n\nToo bad I'm going to have to send you off now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25826] = { id = 25826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver the Goods", description = "Alright, {name}, I need you to get this oil back to Pozzik on the Speedbarge, and let him know the good news!", sourceObjective = "Deliver the Barrel of Oil to Pozzik on Fizzle & Pozzik's Speedbarge in Thousand Needles.", progress = "Hello again, friend. Is that oil?!", completion = "It is oil! You're the best, {name}!\n\nToo bad I'm going to have to send you off now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25830] = { id = 25830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Living Lorekeeper", description = "You have awakened the ancients, {name}, but the wilderness spirit Aessina remains silent. With her help, we can turn the tide of this attack and undo the damage Twilight's Hammer has done.\n\nThere may be one who can help us. The oldest of the trees, Nordu, stood in the center of what is now the Flamewake for thousands of years. His wisdom is as old as this mountain. If that old tree still lives, perhaps he can awaken Aessina... seek him out.", sourceObjective = "Seek out Nordu, an Ancient of Lore, at the Flamewake in Mount Hyjal.", completion = "I ... have not yet ... perished.", sourceObjectiveStatus = "unverified-source-field" }
quests[25832] = { id = 25832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Aviana", description = "{name}, you've done all you can here. This whole cavern is about to collapse in on itself!\n\nI'll gather up the last of our feathered steeds and ensure that the flamegate is sealed behind me.\n\nYou should go on ahead and let Aviana know that this abominable hatchery is no more!", sourceObjective = "Return to Aviana at the Shrine of Aviana in Mount Hyjal.", completion = "<Aviana's face is immobile as you tell her about what happened within the hatchery.>\n\nThey stole my eggs, {class}. They took them to that foul place. Corrupted them.\n\nMy children stolen, tormented, killed in a vat of flame... Yes, we will make Twilight's Hammer pay.\n\nBut I confess, part of me wants to fly up and simply watch this whole... world... burn.", sourceObjectiveStatus = "unverified-source-field" }
quests[25834] = { id = 25834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death by Proxy", description = "Can you hear them fighting down below, {name}? It would appear that the Grimtotem tauren are no longer in the good graces of the Horde. I don't know what happened, but we can turn this to our advantage.\n\nI will arrange a meeting with an ambassador from the Grimtotem. What I need you to do is put together a peaceful offering.\n\n<Force Commander Valen points to Cookie.>\n\nTalk to \"Cookie,\" {name}. He's already been briefed on what we need to do.", sourceObjective = "Speak with \"Cookie\" McWeaksauce at Northwatch Expedition Base Camp in Stonetalon Mountains.", completion = "The name be \"Cookie,\" lad: greatest cook 'cross Azeroth. Now the Commander's told me what we be needin' to do. To gain audience with the Grimtotem chief we're gonna have to cook up the finest of tauren cuisine.\n\nYe get me the ingredients and I'll put together an offerin' no tauren could refuse. Not even a grim tauren or whatever them things be.", sourceObjectiveStatus = "unverified-source-field" }
quests[25835] = { id = 25835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Freewind Post", description = "Alas, it's time for you to leave. How quickly the chicks fall from the nest. Or, something.\n\nAnyway, you've done solid work here, my friend, but Quentin and the night elves have been crying that they urgently need your help with the Grimtotem at Freewind Post to the northwest.\n\nIf you ask me, it's a lost cause, but who knows... maybe with your help they'll actually succeed?", sourceObjective = "Speak with Quentin at Freewind Post in Thousand Needles.", completion = "I'm glad that Fizzle finally sent you here. We're helping the tauren to retake Freewind Post and push back the Grimtotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[25836] = { id = 25836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Freewind Post", description = "Well, it looks like it's time for us to part ways, at least for a while. To the northwest, the tauren of Freewind Post are in desperate need of your assistance in pushing back the Grimtotem clan!\n\nYou know, you've been such a great help around here, I bet you're going to be their <hero/heroine> in no-time!", sourceObjective = "Speak with Thalia Amberhide at Freewind Post in Thousand Needles.", completion = "I am honored that you have come to help, {class}. It was kind of Pozzik to send you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25837] = { id = 25837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Peace Offerin'", description = "To make the perfect peace offerin', I be needing the following ingredients:\n\nKalimdor eagle eggs, obtained from Kalimdor eagle nests. They be scattered about the forest to the west.\n\nRam haunches! You'll find ram haunches on Stonetalon rams.\n\nThe last ingredient be a little tougher to come by, but we be needin' it to make the ramlette. Head southwest to Boulderslide Canyon and find the kobold caves. Kill the kobolds and take their special cheese.\n\nBring it all back and I'll cook up a masterpiece!", sourceObjective = "Collect 6 Kalimdor Eagle Eggs, 8 Ram Haunches and 10 Boulderslide Cheese pieces.", progress = "This ramlette ain't gonna make itself!", completion = "Stand back, {name}, there's about to be a flavor explosion and I wouldn't want ya gettin' hurt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25838] = { id = 25838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help from Steelgrill's Depot", description = "With your help, we've managed to push toward Frostmane Retreat. Our forces will soon be in position to dwindle down the Frostmane trolls' reserves, leaving their village open to attack.\n\nThat's where the Gnomeregan covert ops team comes in. Their technicians have figured out a way to deploy operatives behind enemy lines without alerting the Frostmanes to our presence. Head to Steelgrill's Depot, just northeast of town, and speak with Delber Cranktoggle. He'll tell you more about it.", sourceObjective = "Speak to Delber Cranktoggle at Steelgrill's Depot.", completion = "Ah, you must be the {race} that Captain Tharran said he'd be sending. I've already used the deploy-a-tron to get most of the covert ops team into position at Frostmane Retreat. They're just waiting on your arrival.", sourceObjectiveStatus = "unverified-source-field" }
quests[25839] = { id = 25839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ultrasafe Personnel Launcher", description = "The cataclysm has brought our enemies closer to home, so the chief of Gnomeregan covert operations asked me to build a device to dispatch personnel quickly and quietly to any corner of Dun Morogh.\n\nBehold, the ultrasafe personnel launcher!\n\nWith a jolt of electricity and the benefit of a VLD parachute system, uh, that's 'very late deployment' for you laymen, this baby'll get you to the front in no time. Just hop aboard and prepare for flight! Slamp Wobblecog will be waiting for you in the drop zone.", sourceObjective = "Use the Ultrasafe Personnel Launcher to deploy to Frostmane Retreat.", progress = "Did you survive the deployment?", completion = "Don't worry, the feeling of being zapped won't stay with you for more than a few minutes. All in all, it's not a bad way to get where you're going. That parachute system needs some work, though. Very late deployment, indeed. Sometimes, too late. Anyway, we have a mission to carry out.", sourceObjectiveStatus = "unverified-source-field" }
quests[25840] = { id = 25840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Resistance", description = "The Frostmane chieftain died in the initial trogg onslaught, but they've been led by a well-respected warrior ever since. Battok the Berserker was the one who organized the Frostmane retreat, the construction of the new village, and the strikes against Kharanos and the mountaineers.\n\nIf we remove Battok, the Frostmanes' organization should crumble, leaving the mountaineers free to pick off the survivors. Battok will be in the village, just east of here.", sourceObjective = "Slay Battok the Berserker and 5 Frostmane Warriors in Frostmane Retreat.", completion = "Excellent job, {name}. With Battok dead, I'll send the signal to Captain Tharran. This should be the end of the Frostmane threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25841] = { id = 25841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike From Above", description = "Delber's technicians have been up day and night helping us prepare for this strike. Aside from building and tuning the personnel launcher, his men have prepared the covert operations air wing for a strike on Frostmane Retreat. They'll be waiting for a signal to begin their strikes.\n\nTake this flare with you, and set it off near the cluster of buildings at the northern end of the village, and the buildings at the southern end of the village. The flying machines will make a quick strike at each site.", sourceObjective = "Use the Signal Flare to call in airstrikes at the northern and southern ends of Frostmane Retreat.", completion = "Both you and the air wing performed admirably. There's no way that the Frostmanes will remain here now. All that remains is to begin mopping up the survivors.", sourceObjectiveStatus = "unverified-source-field" }
quests[25842] = { id = 25842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firefight", description = "It is... too late for me. Burned to all but the core. I have lived eons ... yet still my end seems sudden.\n\nNew life can spring from old. I still have wisdom to pass on. Please... do not let them take me before my work is done.\n\nKeep the tormentors at bay... just a little longer, {class}.\n\nGive me minutes, and I will give you a thousand lifetimes.", sourceObjective = "Kill 5 Fiery Tormentors to keep them from Nordu.", progress = "Are you there, {class}? My vision is failing... I hear fighting...", completion = "Thank you, {race}.\n\nI am ready now.\n\nAll that I am, and all that this forest once was... it is now yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[25843] = { id = 25843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortolla's Revenge", description = "The mountain blooms again! If we act quickly, we can press our advantage.\n\nOur old friend Tortolla, the turtle ancient, is already on the move. At his own pace, of course...\n\nFind Tortolla east of here, at the head of the path leading down into the scorched plains. Our strongholds there fell early in the campaign, but perhaps now we can reclaim them.", sourceObjective = "Speak to Tortolla at the Scorched Plain in Mount Hyjal.", completion = "{race}.\n\nI remember you. Savior of my children.\n\nThe time has come. For vengeance.", sourceObjectiveStatus = "unverified-source-field" }
quests[25844] = { id = 25844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sating the Savage Beast", description = "You heard the commander, {name}. Deliver me perfect offerin' to the Grimtotem ambassador! Him and his crew be waitin' for you at the bottom of the southeastern path.\n\nThis is sure to put us in the good graces of their chieftain!", sourceObjective = "Deliver the Meaty Offering to Ton Windbow at Grimtotem Post in Stonetalon Mountains.", progress = "<Ton Window sniffs at the air and raises his left hand.>\n\nYou have brought something for us?", completion = "<Ton and his bodyguards scarf down the meaty offering.>\n\nThis... this is the greatest thing I have ever tasted. You may prove to be a valuable ally, but before the Grimtotem agree to work with the Alliance, you must agree to our terms. I will now give to you those terms as told to me by my leader. Take them back to your commander and see if he accepts.", sourceObjectiveStatus = "unverified-source-field" }
quests[25845] = { id = 25845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terms of Service", description = "Grimtotem need weapons! The Horde, empowered by their Warchief and with the help of their new goblin allies, have amassed powerful weaponry. Our armaments are simply no match for their firepower. Supply the Grimtotem with strong weapons and we will work together to destroy the Horde!\n\nThese are our demands! Supply the Grimtotem and we will fight for the Alliance!", sourceObjective = "Deliver the Grimtotem Terms of Service to Force Commander Valen at Northwatch Expedition Base Camp in Stonetalon Mountains.", progress = "Well???", completion = "Weapons, eh?\n\n<Force Commander Valen sighs.>\n\nI'm about to make an executive decision here, {name}. Let's hope this pays off, else King Wrynn will have my head!", sourceObjectiveStatus = "unverified-source-field" }
quests[25846] = { id = 25846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundig Darkcloud, Chieftain of the Grimtotem", description = "The Grimtotem chieftain awaits your arrival, {name}. Take the weapon crates with you and head to Grimtotem Post, south of here.\n\nGood luck, {name}. Should anything happen to you I will personally notify your next of kin and let King Wrynn know what you have done for the Alliance.", sourceObjective = "Deliver the Alliance Weapon Crates to Grundig Darkcloud at Grimtotem Post in Stonetalon Mountains.", progress = "Do you have the weapons?", completion = "These are fine weapons! Powerful steel! My warriors will be unstoppable armed with such weaponry. Magatha smiles down upon you, {name}.\n\nThere is but one thing I ask of you, perhaps two.", sourceObjectiveStatus = "unverified-source-field" }
quests[25847] = { id = 25847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Supremacy", description = "Throughout all of Greatwood Vale you will find Grimtotem under attack by the Horde. Hellscream's armies show no mercy and no compassion, killing anything that stands in their way.\n\nBut no more! Take the armaments you brought for us and find Grimtotem in battle with the Horde. Give them the weapons of the Alliance and watch as they destroy their Horde assailants! Go, there is much work to do, ally.", sourceObjective = "Use the Alliance Weapon Crate to arm 12 Grimtotem.", progress = "Have you armed the Grimtotem?", completion = "The fight is far from over, {name}. The Horde generals still live...", sourceObjectiveStatus = "unverified-source-field" }
quests[25848] = { id = 25848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Downfall", description = "By the time that we received word that Hellscream had sent another mag'har orc to oversee the Horde troops in southern Stonetalon, it was too late. Camp Aparaje was burned to the ground and all Grimtotem in the area incinerated.\n\nNow the Horde have four of their most fearsome generals commanding the battle for Greatwood Vale, including the mag'har, General Glubgok.\n\nYou must travel to the ruins of Camp Aparaje, south of here, and kill the generals. We stop the Horde NOW! Return to me with their mark!", sourceObjective = "Kill the Horde generals at Camp Aparaje and recover the Insignia of the Horde General.", progress = "Are the generals dead?", completion = "<Grundig crushes the insignia in his massive fist.>\n\nYes, ally, you have done it! It will take Hellscream weeks to recover from this blow. Southern Stonetalon belongs to the Grimtotem... and the Alliance, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[25849] = { id = 25849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Archaeology Attacks", description = "Listen, <lad/lass>, any good archaeologists know the risks that come with the job. If you don't unearth an ancient evil or get cursed by wicked spirits at least once in your career, you're not digging up anything worthwhile!\n\nNo, the real archaeologists know that a little thing like fossilized bones reanimating into skeletal creatures is no reason to stop working.\n\nI still need those fossil bones. Collect 'em from the fossil monsters roaming around and bring them back to me, and I'll reward you.", sourceObjective = "Collect 20 Fossilized Bones from Living Fossils.", progress = "Don't be coy about it, now! Bring back a good armful of 'em!", completion = "See? Not bad, eh? Why, I almost wish all my finds decided to dig themselves up for me. It'd make my job a lot easier!\n\nOf course, you made it easier too, {name}. Much obliged.", sourceObjectiveStatus = "unverified-source-field" }
quests[25850] = { id = 25850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike the Earth!", description = "In case you didn't notice, the land here in the Wetlands is pretty messed up. Floods, earthquakes... and on top of it all, even the ground's got a wild hair now.\n\nI never thought we'd be attacked by our own dig site, but sure enough, big chunks of it are now rampaging around trying to flatten any dwarf they see.\n\nYou look like a strong, strapping young {race}... mind going down there and slapping some sense into the clods?", sourceObjective = "Kill 7 Paleolithic Elementals.", completion = "That's showin' em what for! Good on you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25851] = { id = 25851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dances with Grimtotem", description = "Return now to your leader and tell him all that you have done for the Grimtotem. Tell him that the Alliance may pass freely across our borders.", sourceObjective = "Report to Force Commander Valen at Northwatch Expedition Base Camp in Stonetalon Mountains.", completion = "Outstanding work, {name}! Now our forces only need to worry about the Horde as they enter Stonetalon.", sourceObjectiveStatus = "unverified-source-field" }
quests[25852] = { id = 25852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All's Clear", description = "Pack up your gear, {name}, it's time to join up with the rest of the Northwatch forces in Southern Barrens. Your first mission in Southern Barrens should be fairly straightforward.\n\nTwo days ago we received a distress signal from Commander Walpole. He and his battalion are pinned down in Stonetalon Pass, just outside of Honor's Stand. They've got Horde all over the place! Get there and help him out. I'll forward news of our alliance with the Grimtotem to Northwatch command.", sourceObjective = "Report to Commander Thomas Walpole at Stonetalon Pass in Southern Barrens.", completion = "You say the Grimtotem are no longer a threat? That's great, but we've got Horde all up our keesters!", sourceObjectiveStatus = "unverified-source-field" }
quests[25853] = { id = 25853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tooling Around", description = "I'm in charge of supplying this dig. It's not that bad, but having to pick up and move out so fast wasn't exactly ideal!\n\nArchaeologists need tools, you know. You can't run around pulling up priceless antiquities with your bare hands. If you're going back to the dig site, can you bring back the tools that got left behind?", sourceObjective = "Collect 6 Archaeologist's Tools.", progress = "Are they all here? We left a lot back there.", completion = "That's a relief! Maybe we can dig our way out of the hole we're still in, eh?\n\nNo, nevermind, just a bad joke.", sourceObjectiveStatus = "unverified-source-field" }
quests[25854] = { id = 25854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'll Call Him Bitey", description = "Have you heard some raptors are intelligent enough to be domesticated? It's true! I've seen hunters tame them.\n\nIt gets quite lonely out here, you know, even with Wenna to keep me company... a pet's just what I need to brighten my spirits. A little baby raptor would be the best!\n\nIf you're out there slaughtering the adults, would you mind bringing me back some mature eggs? You can tell if they're ready to hatch by the wobbling.", sourceObjective = "Collect 6 Wobbling Raptor Eggs.", progress = "Do you have enough eggs? I can't take my chances with only one. Statistics, you know.", completion = "Wonderful! These should be ready to hatch within the day...\n\nNow I just need to cobble up a raptor pen before they all hatch nigh-simultaneously. What could go wrong?", sourceObjectiveStatus = "unverified-source-field" }
quests[25855] = { id = 25855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gizmos and Gadgets", description = "I've been coming up short on parts recently for my engineering projects, and the other day I finally saw why: the Mosshide gnolls have been making off with them!\n\nI don't have any idea what they could possibly want them for, but I need those gizmos back. They're probably strewn all over the marsh by now, but if you see any, could you gather them and bring them back?", sourceObjective = "Find 7 Swiftgear Gizmos.", progress = "Did you find them?", completion = "Oh, wonderful! I'll be able to start reassembling these right away. Thank you so much!", sourceObjectiveStatus = "unverified-source-field" }
quests[25856] = { id = 25856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Hides", description = "I've skinned crocs in the wetlands for years, {class}. Things have changed though.\n\nYou see, not to bore you with a sob story, but when the cataclysm flooded Menethil Harbor, our house went with it. My wife and kids don't have a place to stay, and I need to make as much money as I can to get us under a roof again.\n\nI've been skinning crocs 'til I was too tired to move, but I still need more skins to sell. If you bring me some croc hides, I'll pay you a bit for them.", sourceObjective = "Collect 10 Marshy Crocolisk Hides from Wetlands Crocolisks.", progress = "Got any croc hides for me?", completion = "I'm much obliged, {class}. This'll go a ways towards getting my family back on their feet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25857] = { id = 25857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Horrorjaw", description = "I've been tempted to go after the big kill... the largest crocolisk out there, Horrorjaw. His hide alone would be enough to get my family out of this hole.\n\nBut I'm no fool. One mistake and I could lose a leg, or my life, and then where would my wife and kids be? Still homeless and without a father to care for them.\n\nIt's not my proudest moment, but I'll pick my family's safety over pride any day. Please, {class}... hunt Horrorjaw for me. You'll find him in his shady pool to the north, lurking.", sourceObjective = "Slay Horrorjaw and collect Horrorjaw's Hide.", progress = "Did you get it? Do you have Horrorjaw's hide?", completion = "Amazing! You're a true hero, {name}. I'll never forget what you've done for me and my family.\n\nI know it's not much, but please, take this with my blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[25858] = { id = 25858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Her Lady's Word", description = "Lady Sira'kess has begun preparations for the ritual of summoning, but the Crucible of Nazsharin has been stolen from us. The Kvaldir have surely taken it with them as they retreated to shallower waters.\n\nSpeak to the caste leaders to secure a war party, and then lead them in retrieving the artifact from Biel'aran Ridge to the east.\n\nI trust you my Battlemaiden, for you have never failed in any task that I have given you. As I am revered to the Queen, so are you revered to me. Go with my blessings.", sourceObjective = "Speak to Fathom-Lord Zin'jatar, Lady Sira'kess, and Overseer Idra'kess.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "Reinforcements have begun to circle the waters around the ledge, preparing for the attack. They await only your lead.", sourceObjectiveStatus = "unverified-source-field" }
quests[25859] = { id = 25859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Trespass Forgiven", description = "I know that you, like our revered lady, have unfortunate streaks of mercy that you succumb to at times. I would advise against such kindnesses this day. The Kvaldir are proud, and they will strike back if we do not cripple them completely. Kill all that you find.\n\nSadly, I have the inglorious task of making sure none return to the city, so you can go have all of the fun. I will cheer you on though, of course.", sourceObjective = "Kill 20 Kvaldir on the Vrykul Ledge.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "Not one slipped through to the bridge. Not one.\n\nIt was very boring. I'd appreciate it if you shared a little next time.", sourceObjectiveStatus = "unverified-source-field" }
quests[25860] = { id = 25860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At All Costs", description = "We are to begin the ritual immediately, and you are to see to it that we are not interrupted.\n\nSlaughter any Kvaldir that enter the temple. See to it that my priestesses live to see their task complete, no matter the cost.", sourceObjective = "Kill 20 Kvaldir attackers within Quel'Dormir Temple.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "I am trusting you to safeguard us, Battlemaiden.", completion = "Azjentus is to be taken at his word. Lady Naz'jar's Honor Guard should be sufficient to see the rest of the ritual through.", sourceObjectiveStatus = "unverified-source-field" }
quests[25861] = { id = 25861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting An Example", description = "The High-Shaman are in the buildings nearby, chanting and taunting, but not daring to approach me. These Kvaldir find their courage and strength only in the mist. They are a pitiful nuisance beneath the waves.\n\nI came bearing a message. If your ladyship has the time, bring a high-shaman to my feet that I might deliver this message to him and his people.", sourceObjective = "Bring a Kvaldir High-Shaman to the feet of Executioner Varathress.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "If your ladyship has the time, bring a high-{class} to my feet that I might deliver a message to him and his people.", completion = "My scythe is sated. Thank you, my lady.", sourceObjectiveStatus = "unverified-source-field" }
quests[25862] = { id = 25862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Property", description = "Our revered lady has sent me to aid you in your task. She wants you to retrieve the stolen Crucible of Nazsharin and bring it back here as soon as you can.\n\nShe grows impatient to start the ritual of summoning so that we might fully begin our preparations for war.", sourceObjective = "Retrieve the Crucible of Nazsharin.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "The crucible looks far too heavy to carry on your own, but more than enough naga forces remain to prepare it for transport.", sourceObjectiveStatus = "unverified-source-field" }
quests[25863] = { id = 25863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chosen Burden", description = "With the Crucible of Nazsharin, all that remains is to inform Lady Naz'jar of your success.", sourceObjective = "Return to the western edge of the Biel'aran Ridge with news of the Crucible of Nazsharin.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "Well done, my Battlemaiden.\n\nThis crucible will serve as a font of power for our summoning ritual. With it, Sira'kess will beckon our allies from the depths to bolster our already swelling forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[25864] = { id = 25864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dinosaur Crisis", description = "We've been getting more and more reports of raptor attacks in the area. I'm seeing to it that this place is safe enough for more settlement to start occuring, so I've put a bounty on the buggers.\n\nA lot have been cleared out already, but the Highland raptors to the north have been growing in number. That won't be true for long, now will it?\n\nClear out a good deal of Highland raptors, and I'll have a nice reward for you.", sourceObjective = "Kill 8 Highland Raptors of any kind.", completion = "A job well done. Consider this reward not from me, but from Ironforge; the preservation of Khaz Modan is a matter that concerns every dwarf.", sourceObjectiveStatus = "unverified-source-field" }
quests[25865] = { id = 25865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosshide Job", description = "You seem trustworthy enough to help me out with my real problem, {name}. I was sent here by Ironforge to recover a shipment of gold ingots.\n\nThe ingots are part of the Ironforge Royal Treasury, stamped with the royal seal... only an idiot would steal them for profit, far too easy to trace. Oddly enough, this area is full of idiots: Mosshide gnolls.\n\nI don't know how many gnolls you've fought before, but they're foul and brutal beasts, and dangerous. I need you to slay them and recover the missing ingots.", sourceObjective = "Recover 8 Ironforge Ingots from Mosshide Gnolls.", progress = "There should be about eight ingots stolen.", completion = "Well done! The Ironforge Guard appreciates this, {name}. You've done our city a fine favor.\n\nBut something new has come up...", sourceObjectiveStatus = "unverified-source-field" }
quests[25866] = { id = 25866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Trappers", description = "You may have seen them while you were out, but the Dark Iron clan has been spotted in this area. They're never up to any good, and it looks like they're kidnapping the Mosshide gnolls for some reason.\n\nI don't know what their game is, but we're putting a stop to this before more foul play occurs. Go and stop them.\n\nAnd if you're worried about fairness, try askin' them politely first and see how far that gets you.", sourceObjective = "Kill 10 Dark Iron Trappers.", completion = "I don't suppose they agreed to come along quietly? Didn't think so.", sourceObjectiveStatus = "unverified-source-field" }
quests[25867] = { id = 25867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnoll Escape", description = "I know we were just attacking the gnolls ourselves, but I'm not about to let the Dark Iron capture them as slaves. For one, we found the thieves and took back what was missing, so justice is served; for another, whatever work the Dark Iron will be putting them to isn't something I want to allow.\n\nEither way, the gnolls need to be freed. The trappers should have keys on them, so use those to open the cages.", sourceObjective = "Obtain Trapper's Keys from Dark Iron Trappers and use them to free 6 Gnolls from the Gnoll Cages.", completion = "That should do it! The more gnolls those fools have to chase after, the easier it'll be to keep them in line.", sourceObjectiveStatus = "unverified-source-field" }
quests[25868] = { id = 25868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yorla Darksnare", description = "I've found out who's pulling the strings on this operation here. Yorla Darksnare is directing the Dark Iron dwarves from a camp to the east, and it might've been orders to have the gnolls steal Ironforge's gold in the first place.\n\nWhat's more, she's a wanted criminal... she's been inciting rebellion and attacks against Ironforge since Magni was still alive.\n\nShe can't slip through our fingers this time, {name}. Go and get her!", sourceObjective = "Slay Yorla Darksnare.", completion = "A job well done! You've brought one of Ironforge's most wanted to justice today, {name}. I'd say you've earned a mighty fine reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[25869] = { id = 25869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem in the Post", description = "The journey ahead must begin with you killing the Grimtotem invaders at Freewind Post. If you can't stop them here, we won't be able to move into their territory.", sourceObjective = "Slay 10 Grimtotem Invaders.", completion = "Grim business, that.<Quentin coughs.>\n\nNo pun intended.", sourceObjectiveStatus = "unverified-source-field" }
quests[25870] = { id = 25870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem in the Post", description = "You must do away with the Grimtotem invaders at Freewind Post. They brought it on themselves, the cowards!\n\nWe can't take the fight to their territory with our back to them. Please help us take back our home, {class}.", sourceObjective = "Slay 10 Grimtotem Invaders.", completion = "It's a good start. Normally, I wouldn't wish harm on any of the Earth Mother's creatures.\n\nBut attacking us at our most vulnerable moment?! They deserve to die!", sourceObjectiveStatus = "unverified-source-field" }
quests[25871] = { id = 25871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save the Sentinel", description = "<Brienna waves a note around with Taur-ahe markings on it.>\n\nThose monsters have captured one of our sentinels! They're threatening to kill her if we don't pull back!\n\nWe don't negotiate with cowardly beasts! Please, if you can, rescue her before it's too late, {class}.", sourceObjective = "Rescue the Feralas Sentinel.", completion = "Thank you for freeing her, {name}. Those Grimtotem monsters would have killed her in cold blood.", sourceObjectiveStatus = "unverified-source-field" }
quests[25872] = { id = 25872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brave and the Bold", description = "<Rau dismissively waves a note around with Taur-ahe markings on it.>\n\nThose mongrels have captured one of our braves! They're threatening to kill him if we don't pull back!\n\nWe'll never allow those Grimtotem cowards to keep Freewind Post! Please, rescue him before it's too late, {class}.", sourceObjective = "Rescue the Freewind Brave.", progress = "Where's our brave? Is he alive?", completion = "Thank you for freeing him, {name}. Those Grimtotem would have killed him in cold blood.", sourceObjectiveStatus = "unverified-source-field" }
quests[25873] = { id = 25873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horn of the Traitor", description = "Here lies the broken body of the Freewind Post lorekeeper, Montarr. The aged tauren's body is broken, lying in a pool of his own blood.\n\nA trail of droplets leads back to the inn....", sourceObjective = "Collect Longhorn's Horn.", progress = "What's this, {class}?", completion = "A traitor amongst the tauren?\n\nI've never heard of such a thing. Clan rivalries and warfare are one thing, but killing your own in cold blood.\n\n<Quentin shakes his head in disbelief.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25874] = { id = 25874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horn of the Traitor", description = "Here lies the broken body of the Freewind Post lorekeeper, Montarr. The aged tauren's body is broken, lying in a pool of his own blood.\n\nA trail of droplets leads back to the inn....", sourceObjective = "Collect Longhorn's Horn.", progress = "{name}? What news do you have?", completion = "The cliffwatcher was a Grimtotem spy?! No wonder we had no warning!\n\n<Thalia seethes with barely contained rage.>\n\nI don't want that damned thing. Throw it into the water and let the Longhorn name never be spoken again!", sourceObjectiveStatus = "unverified-source-field" }
quests[25875] = { id = 25875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnome on the Inside", description = "Mirkfallon Lake is crawling with Horde. The goblins have set up shop and they aren't going to leave until all the oil under Stonetalon is sucked dry.\n\nThankfully I have a gnome on the inside that's been collecting information for us. If anyone knows what's going on with that bomb, it's my inside gnome.\n\nMake your way to the Sludgewerks, north of here, and find Minx. She'll be disguised as a \"goblin\" pump controller.", sourceObjective = "Seek out Minx who is disguised as a \"Goblin\" Pump Controller at the Sludgewerks in Stonetalon Mountains.", completion = "Get in here and hug a wall! I can't risk blowing my cover!", sourceObjectiveStatus = "unverified-source-field" }
quests[25876] = { id = 25876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Up There!", description = "Listen, I've been tracking this bomb since you rescued me in Ashenvale. Whatever they're doing with it is going to happen real soon.\n\nAt the top of the large oil rig is a control room. Inside that control room you'll find a Krom'gar log book. That log book is the key to where this bomb is heading. Get up there and get the log book! Bring it back here and I'll decipher it for you.", sourceObjective = "Steal the Krom'gar Log Book.", progress = "Did you recover the log book?", completion = "OH NO! They plan to \"test\" the bomb at Thal'darah Grove! That's the school for young druids located in the heart of Battlescar Valley. You've got to return to Barus with this information! Master Thal'darah must be warned!", sourceObjectiveStatus = "unverified-source-field" }
quests[25877] = { id = 25877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Time for Goodbyes!", description = "RUN! Get out of here, {name}. Get back to Barus and inform him of what you've discovered. He'll arrange for you to get safely across Battlescar Valley to Thal'darah Overlook.\n\nIt's not too late to save those young druids!", sourceObjective = "Return to Scout Commander Barus at Mirkfallon Post in Stonetalon Mountains.", completion = "Blasted Horde! I've got friends at that grove. Hopefully you know how to ride a hippogryph. We've got to get you to Master Thal'darah at the overlook immediately!", sourceObjectiveStatus = "unverified-source-field" }
quests[25878] = { id = 25878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schemin' That Sabotage", description = "Goblins... What would this world be without goblins? I'll tell you what: CLEAN!\n\nThose filthy little scum suckers have planted their oil pumps all over the lake with the hope of extracting every last drop of oil that exists in Stonetalon. At each oil pump they've stationed an oil pump controller whose sole job it is to watch the pump and make sure nothing goes wrong.\n\nSomething is about to go wrong.\n\nTake out the goblin pump controllers and take their pump controls. Use 'em to overload the pumps!", sourceObjective = "Use the Goblin Pump Controller to destroy 4 Goblin Oil Pumps.", completion = "I could see the explosions from here, {name}! The Horde won't be refueling from Mirkfallon anymore, thanks to you!", sourceObjectiveStatus = "unverified-source-field" }
quests[25879] = { id = 25879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lumbering Oaf Problem", description = "Ever seen a hobgoblin? They're another vile goblin creation. Take a goblin, make it even uglier, fatter, bigger and stupider and you have a hobgoblin. Add to all of that a nasty mean streak and we've got a problem.\n\nThese lumbering oafs wander the Sludgewerks and Mirkfallon Lake, acting as muscle to the goblins.\n\nGet out there and thin 'em out. Permanently.", sourceObjective = "Kill 10 Lumbering Oafs.", completion = "Slowly, but surely, we pick away at the Horde's numbers. They won't have a leg to stand on when this war really opens up.", sourceObjectiveStatus = "unverified-source-field" }
quests[25880] = { id = 25880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Master Thal'darah", description = "There are dozens of students at Thal'darah Grove. Most of them have no means of defending themselves, ripe for the slaughter.\n\nYou must get word to Master Thal'darah of the Horde's plans. He will direct you in what you must do next.\n\nFiora Moonsoar has granted you the use of her fastest hippogryph. Take it now to Thal'darah Overlook! Don't look back, {name}! The Horde must be stopped!", sourceObjective = "Report to Master Thal'darah at Thal'darah Overlook in Stonetalon Mountains.", completion = "These are dire times, indeed, {name}. Our outpost in Stonetalon Peak has been overrun by fiendish creatures from the depths and the Horde seeks to destroy us. We need a hero, {name}; a soldier of the Alliance strong enough to guide us through these trying times.", sourceObjectiveStatus = "unverified-source-field" }
quests[25881] = { id = 25881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Wardens", description = "We held out as long as we could, {class}. But the flames... the heat... We lost the whole town.\n\nCaptain Irontree refused to pull back when the flames engulfed us. Our forces are scattered. Maybe some of the others survived? We can mount a counter-attack!\n\nGo into the Scorched Plain and rescue any lost wardens that got separated from the group. Then find Captain Irontree - he's probably taken up a fortified position in the middle of the fighting.", sourceObjective = "Locate and rescue 8 Lost Wardens.", completion = "You've assembled the survivors? Good, good. And the rest of the mountain - healed?\n\nHaha, strike me down! We're on the front lines again!", sourceObjectiveStatus = "unverified-source-field" }
quests[25882] = { id = 25882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hand at the Ranch", description = "Captain Tharran asked me to pass along his thanks for your help and congratulations on a successful mission. He and his men are cleaning up the last of the trolls and tending to the wounded.\n\nHe also wanted me to ask you to check out reports about troll raids on the Amberstill Ranch to the north. Ask for Sergeant Flinthammer when you arrive.", sourceObjective = "Speak with Sergeant Flinthammer at Amberstill Ranch.", completion = "So you're the one who's been helping Captain Tharran beat back the Frostmane trolls? I've seen your name in the reports. It's good to finally meet you. You might be just the {class} we need to help secure the ranch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25883] = { id = 25883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Disarming", description = "Naga weapons...\n\nAs you cast your vision on the naga Holding Pens, you see dozens of similar stacks of tridents positioned strategically.\n\nDestroying their weapons could only hamper whatever wicked designs they are carrying out in this region...", sourceObjective = "You must destroy 6 sets of Naga Tridents.", progress = "Have you destroyed the naga arsenal?", completion = "You're confident that your assault on the naga armaments has made an impact on their effectiveness.", sourceObjectiveStatus = "unverified-source-field" }
quests[25884] = { id = 25884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come Hell or High Water", description = "Oh fer the love of...\n\nI know our survivor friend here means well, but the lad's been severely traumatized.\n\nThere only be one way ta deal with these accursed beasts, an' that be a fine dwarven axe buried hilt-deep in the noggin.\n\nPile up enough o' their corpses an' they'll think twice before fiddlin' with yer tasty bits.\n\nMark me words <laddie/lassie>, them buggers don't like the sight o' their own blood any more than you or I.\n\nNow git out there an' give 'em what fer!", sourceObjective = "Kill 12 Zin'jatar Naga at The Clutch in Kelp'thar Forest.", completion = "The waters surrounding the Holding Pens are red with the blood of the naga.\n\nRendel would be proud!", sourceObjectiveStatus = "unverified-source-field" }
quests[25885] = { id = 25885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What? What? In My Gut...?", description = "Wha...what IS this!?\n\nThere's great pain growing... from deep in my bowels.\n\nI think... ugh... they must have poisoned me!\n\nThey fed us strangely glowing seaweed that they grow around their stronghold...\n\nI think these cramps will worsen if I don't get more soon...\n\nPlease, {race}. Try to find me some!", sourceObjective = "Collect 7 Wiggleweed Sprouts from Shimmerspine Harvesters in The Clutch.", progress = "Were you able to find me any of their seaweed, {class}?", completion = "Yes, yes. This is the stuff.\n\nMaybe I can gradually eat less of it and avoid that side-effect.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25886] = { id = 25886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressing the Advantage", description = "It looks like most of the Twilight's Hammer has fallen back to regroup for another assault. Their most dedicated are staying behind to hold the line. This is our chance to whittle away at their leadership.\n\nRange out along the Scorched Plain and crush the Twilight Field Captains. We'll remove them from the equation!", sourceObjective = "Slay 4 Twilight Field Captains.", progress = "You've given our forces a second wind, {name}. How goes the fight?", completion = "Terrific! Twilight's Hammer will no doubt try to re-take the mountain, but they'll have to do so without the leadership of those fat-for-brains thugs.", sourceObjectiveStatus = "unverified-source-field" }
quests[25887] = { id = 25887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wake of Destruction", description = "Our time here draws to a close. I must somehow follow the trail of these naga captives if we are to discover their purposes in this region.\n\nBut before I move on, I would see the destruction of this operation!\n\nNevermind their numbers, I have a plan that has the potential to even the odds.\n\nOutside this cave, famished great sharks, displaced by these naga, seek food.\n\nIn their weakened state, they will be susceptible to suggestion. Use this orb to subdue them, then direct them against our enemy.", sourceObjective = "Use the Orb of Suggestion to subdue a Famished Great Shark, then use it to destroy 12 Zin'jatar at The Clutch.", progress = "With the naga numbers dramatically lessened, we shall be able to finish our destruction of this stronghold.", completion = "It is as it should be.\n\nNow the way is clear to deal these naga a crippling blow.", sourceObjectiveStatus = "unverified-source-field" }
quests[25888] = { id = 25888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decompression", description = "I simply cannot bear the thought of so many others like this soldier imprisoned, surrounded by naga.\n\nSomething must be done to rescue them!\n\nTry this, {name}. Use  it on the prison cells to make them buoyant.\n\nIf we can get them to the surface, at least they stand a chance at being rescued.", sourceObjective = "Use Moanah's Breathstone on 10 Imprisoned Soldiers in The Clutch.", completion = "Let us hope for the safety of those released prisoners.\n\nIn return for your noble efforts, please accept this gift.", sourceObjectiveStatus = "unverified-source-field" }
quests[25889] = { id = 25889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save the Children!", description = "My poor, defenseless young students are stranded at Thal'darah Grove. With the battle raging across Battlescar Valley, they have no means of escaping. We must save the children before the Horde drops their bomb!\n\nTake my hippogryph and use it to rescue the young druids of Thal'darah Grove. Drop them off at the hippogryph post here in town.\n\nSave them all, {name}! You truly are our only hope.", sourceObjective = "Use Master Thal'darah's Hippogryph to rescue 5 Helpless Young Druids from Thal'darah Grove.", progress = "Use the whistle to call for my hippogryph, {name}.", completion = "Praise you, {name}. The hero we have been searching for has finally arrived, and not a moment too soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[25890] = { id = 25890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nespirah", description = "It is clear to me at this point what must be done, {name}.\n\nThe naga can only be obtaining these pearls from one place: Nespirah, the ancient, shelled creature that rests outside of this cave.  Why Nespirah would submit to the naga, however, is beyond my understanding.\n\nWe can enter Nespirah's body cavity through a small tube near the exit to this cave.  I must first fetch my master, then we can meet you on the inside.  We will convene in Nespirah's northwestern entrance.", sourceObjective = "Enter Nespirah's northwestern entrance, then find a way to communicate with it.", completion = "Erunak trusts this task to me?  Very well, let's see what we can learn from the ancient one.", sourceObjectiveStatus = "unverified-source-field" }
quests[25891] = { id = 25891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Ditch Effort", description = "The Horde have signaled a retreat. Look now, they fall back from the field of battle - portends of disaster.\n\nWe must make one final descent into Thal'darah Grove. I could not live with myself if any of our young druids were left behind.\n\nAssist me, hero. I will take the reins. You search for any druids that might be left behind.\n\nWe will go when you are ready.", sourceObjective = "Assist Master Thal'darah in search of any druids left behind at Thal'darah Grove.", completion = "Do you know why the Horde destroys? The Horde destroys because they cannot comprehend beauty. They fear it and that which they fear they must destroy. Why else would they destroy Thal'darah Grove?\n\nTogether, we will make them understand. They will know that what they do comes at a great cost.", sourceObjectiveStatus = "unverified-source-field" }
quests[25892] = { id = 25892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Ground", description = "You'll have to catch me up more later. Right now, we need to get out of here before more naga push in. Make your way back to the forward post on the level below us.\n\nTake my sea horse. We will meet you back there shortly.", sourceObjective = "Use Wavespeaker Valoren's sea horse to return to Admiral Dvorek under the southern terrace in the Ruins of Vashj'ir.", completion = "You made it! After the attack at the forward post, I thought we might be the only ones left. I'm very glad to see you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25893] = { id = 25893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Plan", description = "Jorlan and Hexascrub left to find a way to contact help. The trade lanes aren't far, so there might be a chance of success, but I'm wary to let anyone get their hopes up.\n\nIn truth, we don't have any other options. We're not likely to last much longer here. The naga will find us eventually, and... well... you saw how many of them there were.\n\nYou should go find the two of them on Biel'aran Ridge to the southeast. I'll keep everyone here safe as long as I can.", sourceObjective = "Meet with Engineer Hexascrub on Biel'aran Ridge.", completion = "Impeccable timing. Like clockwork! Trouble comes. You come. Save the day.  Clockwork!\n\nWe've devised our brilliant plan. Gloriously simple, barring the hostility of local life. Simpler yet with a you available!", sourceObjectiveStatus = "unverified-source-field" }
quests[25894] = { id = 25894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostile Waters", description = "Hexascrub came out here with a balloon of some sort that he retrieved from one of our ships. He tried to float it to the top, but those Muckskin Scroungers came out of nowhere and swarmed the thing.\n\nHe's got an idea for another balloon, but we need to make sure that the past doesn't repeat itself. I need you to kill off those gill goblins. Or at the very least, enough of them to make them a bit more wary of us.", sourceObjective = "Kill 10 Muckskin Scroungers.", progress = "These scroungers seem intensely curious about our equipment. Sometimes suicidally so. I wonder what attracts them to it so much.", completion = "Less gill goblins is good!\n\nI'm glad that they're so primitive. I don't think I'd want to be dealing with a race of aquatic tech-freaks right now. Not at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[25895] = { id = 25895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come Prepared", description = "We must always come prepared. Prepared with gear. Prepared with plans. Prepared with gear plans!\n\nAll of the ships in all of the Alliance fleets stow a survival kit. A lot of our tools came from a survival kit. My balloon came from a survival kit too! But now it's gone. I need another survival kit!\n\nThere's a ship to the southeastish. Let's hope that the survivors were dumb and didn't take the survival kit. More survival kit for us!", sourceObjective = "Retrieve an Alliance Survival Kit.", progress = "A whole big box of amazing! That's what it is. I need more amazing in my life.\n\nDon't worry, I'll share.", completion = "Let me see, let me see... flare gun... balloon... no rope. Never any rope. Terribly impractical if you do ask me. Rope should be mandatory.", sourceObjectiveStatus = "unverified-source-field" }
quests[25896] = { id = 25896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devout Assembly", description = "Ah, Battlemaiden. You carry with you the word and the will of our Lady. I might ask a favor of you...\n\nI need Fathom-Caller Azrajar and my Tide Priestesses to return so that we can begin the ritual. Can you carry my will to them as such? You should find them spread upon the temple terrace. Azrajar will be at the stairs to the north.", sourceObjective = "Seek out Fathom-Caller Azrajar midway down the northern stairs and 6 Sira'kess Tide Priestesses on the upper portion of the ruins, and instruct them to return to the temple.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "The threat may not be sure, but the Kvaldir are certainly not fools. They would not return if they did not have some confidence in victory.\n\nThe sooner our allies are summoned, the better. Find my Tide Priestesses.", completion = "The Kvaldir have proved a greater threat than we anticipated, but our plans are not hindered in the least. As our allies arrive, we will have a force more than sufficient to usurp the Tidehunter.\n\nAll that remains is to ensure that the ritual of summoning is completed.", sourceObjectiveStatus = "unverified-source-field" }
quests[25897] = { id = 25897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfurling Plan", description = "Survival kits never have any rope. It makes no sense! No sense at all.\n\nI bet those Kvaldir have rope. They're always riding around in boats, tying knots, dressing in nets. Go take some rope from them! I must have it for our plan to work. Absolutely must.", sourceObjective = "Collect 8 Coils of Kvaldir Rope.", progress = "The rope ties the whole plan together!", completion = "This is great! I love it. It should work per... ewww! Is this stuff braided with hair?\n\nDoesn't matter. Almost done. This thing will be ready in the twist of a rope.", sourceObjectiveStatus = "unverified-source-field" }
quests[25898] = { id = 25898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor and Privilege", description = "All done! I'm confident it will work. And not a scrounger in sight to pop a hole in it this time! Fortuitous.\n\nJorlan already swam up to catch it. Swam up and stopped to wait for it. He said you'd get the honors though. Jorlan's nice like that.\n\nGo to the top with the balloon, take the flare gun from the crate, and scan the horizon for Alliance ships. If you see any, fire the flare towards them. That's it! All there is to it.\n\nSwim. Float. Flare. Rescue! That last part's my favorite.", sourceObjective = "Swim to the surface, retrieve the flare gun, and fire a rescue flare towards the Alliance Ships.", progress = "Those aren't trade ships, those are war ships. Still, this is an incredible stroke of luck. Fire that flare off and pray that they see it.", completion = "Perfect! There's no way they missed that, fighting or not.", sourceObjectiveStatus = "unverified-source-field" }
quests[25899] = { id = 25899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breakthrough", description = "The fiery army that caused so much devastation up the hill has retreated east of here. Only the Scorchlords remain in action. If we can punch a hole through their lines to regroup with Captain Irontree's forces, the whole offensive may collapse.\n\n{class}, I'm in no shape to continue fighting, but you look like you can do some damage. Slay those Scorchlords and regroup with Captain Irontree!", sourceObjective = "Slay 10 Twilight Scorchlords.", completion = "You killed how many? Well, well. Quite a show. I guess my men don't have any more excuses.", sourceObjectiveStatus = "unverified-source-field" }
quests[25900] = { id = 25900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Contact", description = "I can't believe that Nespirah would willingly allow these naga to take residence inside her shell.  As I see it, one of two things has happened: they have convinced her to willingly join their cause, or they have weakened her to a point where she cannot fight back.  Either one is bad.\n\nHere in this chamber, I should be able to communicate directly with Nespirah.  Let us find out for ourselves.  Speak to me when you are prepared, {class}.", sourceObjective = "Observe as Earthmender Duarn attempts to communicate with Nespirah.", progress = "Nespirah needs our help.  If nothing else, I can sense that.", completion = "That didn't go well.  For some reason, the beast won't speak back to me.\n\n<Duarn is clearly frustrated.>\n\nIf only Erunak had not left us!  He would know what to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[25901] = { id = 25901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyjal Recycling Program", description = "Reinforcements! I thought we were going to fight this out to the bitter end.\n\nVery few of the Guardians of Hyjal remain, and our supplies are running out. The battlefield around our holdout here must be littered with serviceable arrows.\n\nI know it's beneath your abilities, but can you gather up our spent ammunition? It's the only way we can replenish our supplies!", sourceObjective = "Gather 15 Warden's Arrows.", progress = "Warden's arrows are crafted of living oak, blessed in the moonwells, and tipped with obsidian arrowheads scrawled with runes invoking the blessings of nature.\n\nThey're not cheap.", completion = "Wonderful! Still sharp. A little blood on the fletching, but they'll fly true.\n\nThank you, {name}. Our defense of Hyjal can continue.", sourceObjectiveStatus = "unverified-source-field" }
quests[25904] = { id = 25904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer and the Key", description = "My Nemesis. Still lives.\nThe servants of fire still come.\nWe must pursue. Into their den.\n\nThe ogres know the way.\nSlay the Field Captains.\nRecover the Glyph of Opening.\n\nThis is the way.", sourceObjective = "Kill a Twilight Field Captain and recover the Glyph of Opening.", progress = "The glyph. Show it to me.", completion = "This power is ancient.\nPrimitive.\nEasy.\n\nWe will use it against them.", sourceObjectiveStatus = "unverified-source-field" }
quests[25905] = { id = 25905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rams on the Lam", description = "The rams we raise and train here at Amberstill ranch have long been the mounts of choice for Dun Morogh's mountaineers. Aye, there're a few here, but not enough to guard my family and all the animals.\n\nA few brave Frostmane raiders have taken to stealing our rams under the cover of night, taking them south into the Tundrid Hills. Would you be willing to help return them? You'll need to get fairly close to them and give a sharp whistle to get their attention. Their training will take over from there.", sourceObjective = "Recover 6 Stolen Rams from the Tundrid Hills by using /whistle.", completion = "The rams you rescued have made their way back into the pen. I've got members of the family on a day and night watch now. Those trolls won't take us by surprise again!", sourceObjectiveStatus = "unverified-source-field" }
quests[25906] = { id = 25906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Third Flamegate", description = "Memorize the glyph.\nTake it within yourself.\n\nDraw it on the ground before the flamegate.\nEast of here.\nEnter the Firelands.\n\nI cannot come with you.\nBut my children await. Inside.\n\nFind Garunda Mountainpeak within the realm of flame.", sourceObjective = "Travel through the flamegate in the Scorched Plain and locate Garunda Mountainpeak within.", completion = "You were sent by the turtle god? Bless his almighty shell! I thought I was trapped down here forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[25907] = { id = 25907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slave Labor", description = "It will take me some time to break through this barrier and communicate with Nespirah.  In the meantime, you can save some of those men that the naga have enslaved in the pits below.\n\n<Duarn produces a length of rope from within his robes.>\n\nThis should come in handy.", sourceObjective = "Use Duarn's Rope to save 8 Enslaved Pearl Miners.", completion = "Excellent work, {name}... although I'm afraid I haven't been nearly as productive as you have.", sourceObjectiveStatus = "unverified-source-field" }
quests[25908] = { id = 25908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stick it to Them", description = "I may be unable to communicate directly with the beast Nespirah, but I can still feel some things indirectly.  For example, I can clearly sense that Nespirah is not happy about the naga's presence here.\n\nWhen we first entered Nespirah's body, I saw dozens of sentinels and enchantresses patrolling the central chamber floor.  Perhaps some of the ancient one's pain will be alleviated if you remove them.", sourceObjective = "Kill 7 Idra'kess Sentinels and 7 Idra'kess Enchantresses.", progress = "<Duarn is too focused on his task to notice your presence.>", completion = "Can you sense it?  If you have an ounce of shaman's blood in you, you must feel the sense of relief in the air.\n\nNespirah is pleased.  Perhaps she will finally speak with us.", sourceObjectiveStatus = "unverified-source-field" }
quests[25909] = { id = 25909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture the Crab", description = "Everything in my body tells me that Nespirah is trying to speak with me, but I cannot hear her.  Perhaps the naga have done something to her voice.\n\n<Duarn thinks to himself for a moment.>\n\nNespirah's voice may be suppressed... that means... we need to find a voice for her!\n\nI've got it!  The Idra'kess have been known to train deepseeker crabs as battle companions.  Use this net to capture a crab, and bring it to me.  You will likely find them prowling the chamber's outer edges.", sourceObjective = "Use Duarn's Net to capture a Deepseeker Crab inside of Nespirah.", progress = "I hope this works.  My skills as a shaman are limited, and I fear that this task may be too much for us.", completion = "<Duarn looks at the crab and disguises a frown.>\n\nIt doesn't look very impressive, does it?", sourceObjectiveStatus = "unverified-source-field" }
quests[25910] = { id = 25910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Time for Mercy has Passed", description = "This cavern is an abomination, {name}. And it's filled with horrors from the depths.\n\nI don't want any of these - things - getting through the portal to the outside world. Slay everything!", sourceObjective = "Slay 10 Molten Tormentors and 4 Shadowflame Masters.", completion = "So it is done.\n\nKnowing that Twilight's Hammer is in league with creatures of malice such as these... it really curdles the blood.", sourceObjectiveStatus = "unverified-source-field" }
quests[25911] = { id = 25911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome News", description = "They'll probably send a skiff over, which may take a bit. I'll stay here to make contact.\n\nYou need to return to the cave immediately and let them know that rescue is on its way. We can only hope that the naga have not found them yet.\n\nGo. Swim fast, {name}.", sourceObjective = "Return to Captain Taylor at the Tranquil Wash.", completion = "That is the best news I've heard in what seems like an eternity. We'll get the survivors moving over there to the surface as soon as possible. Perhaps we can forget that this whole nightmare ever happened.\n\nThank you, {name}. I'm not sure there's anything I can do to repay you for everything you've managed to accomplish in this ocean, but I will try to find a way.\n\nYou should consider meeting us at the ships later, when you finish saying your goodbyes to the naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[25912] = { id = 25912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seen Better Days", description = "The world is unraveling around us, {name}. Old enemies seek to destroy us from one end, while ancient forces close in on the other.\n\n<Elder Sareth'na sighs.>\n\nI have seen better days - brighter days, and I long for them...\n\nAcross Stonetalon Peak lies the ruins of our old outpost - now overrun with darkness. If you happen to go that way, could you search for my sketch book? It holds many happy memories. I would reward you well for its return.", sourceObjective = "Find Elder Sareth'na's Sketch Book.", progress = "Have you found my sketch book?", completion = "You've found it! Elune bless you, child! Perhaps this book will give me the strength to carry on.", sourceObjectiveStatus = "unverified-source-field" }
quests[25913] = { id = 25913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting Them to Rest", description = "As the Horde were marching upon Stonetalon, I noticed that some of the sentinels had fallen ill. Not long after, they started acting strangely. When the first tentacle burst from the ground the ill sentinels began attacking us. We lost the outpost shortly after...\n\nThe sentinels in the peak are now nothing more than shells - husks for something far more sinister. I want you to put the sentinels to rest and retrieve their glaives. Each glaive returned can identify a fallen sister.", sourceObjective = "Recover 8 Sentinel's Glaives.", progress = "Recover the sentinel's glaives, {name}. Each glaive is unique to a sentinel.", completion = "Thank you, {name}. Each glaive has the name of the sentinel it belonged to imprinted upon its blade. We can now send word to their families and put their souls to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[25914] = { id = 25914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Depths!", description = "Tendrils are bursting forth from the earth and terrorizing Stonetalon Peak. My sentinels are hardly making a dent in their numbers.\n\nI suspect that there is a force at the heart of Stonetalon Peak that controls the tendrils. Perhaps if we can put a stop to that force, the tendrils will return to the depths from whence they came!", sourceObjective = "Kill Harbinger Aph'lass and 10 Invading Tentacles.", completion = "I'm afraid that the death of Harbinger Aph'lass has not ceased the tendril attacks. You've done all that you can, {name}, and for that I thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25915] = { id = 25915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Strength of Tortolla", description = "The dark usurper Nemesis fled here when the fires of Hyjal receded. We are not yet strong enough to defeat Nemesis, {name}, but we may be able to turn his own strength against him.\n\nI will send a child of Tortolla with you, one of the children you freed earlier from the Twilight's corruption.\n\nSearch the depths of this cave for a Nemesis Crystal, and allow the young turtle to examine it.\n\nSee me if you lose your companion!", sourceObjective = "Escort a Child of Tortolla to a Nemesis Crystal. See Garunda Mountainpeak if you lose your companion.", progress = "What has the little one learned, {name}?", completion = "Ah yes, yes... the secret strength of Nemesis, unearthed here in these caverns.\n\nWe know all that we need to know, {name}. It is time to finish this.", sourceObjectiveStatus = "unverified-source-field" }
quests[25916] = { id = 25916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Through", description = "A trained shaman has the ability to communicate with the four elements of earth, fire, air and water.  This is known.\n\nWhat is not as widely known, however, is the presence of a fifth element.  This element is not as clearly described as the other four, but it has to do with the shared... commonality between all living creatures.\n\nMy theory is that the crab, as a creature of the sea, is close enough to Nespirah that, with the elements' coaxing, we can convince it to act as Nespirah's mouthpiece.", sourceObjective = "Observe as Earthmender Duarn attempts to speak with Nespirah.", progress = "The ritual is not yet complete, {name}.", completion = "I had assumed that the naga were only here for those pearls.  No, this makes much more sense.  If they had Nespirah's power under their control, the amount of damage the naga could do would be catastrophic!\n\nSomething must be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[25917] = { id = 25917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Are Not Alone", description = "<Duarn closes his eyes, pauses, and nods.>\n\nNespirah has just informed me that we are not the only people fighting inside of this shell.  A small group of Alliance slaves has escaped and is currently fighting off the naga on the other side of the shell, up on the ledge that overlooks Nespirah's heart.\n\nGo find them, {name}, and see what help they can lend us.  With their aid, we may be able to rouse Nespirah from her torpor.\n\nI will remain here, should you need anything.", sourceObjective = "Find the Alliance survivors inside of Nespirah in Vashj'ir.", completion = "{name}... is that you?", sourceObjectiveStatus = "unverified-source-field" }
quests[25918] = { id = 25918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hopelessly Gearless", description = "I honestly don't know how we've survived this long.  The naga took my armor and weapons, and left me with rags and a mining pick... and THAT snapped in half long ago.\n\nIf we're to stand any hope of turning the tide, I'm going to need something to fight with... as will my companions, though they may be too proud to admit it.\n\nI've seen weapon racks in the naga storage areas nearby.  I'm not accustomed to fighting with a trident, but it'll sure be better than fighting with my fists.", sourceObjective = "Obtain 4 Purloined Polearms from the weapon racks inside of Nespirah.", progress = "In my youth, I was given some training on spearfighting.\n\n\"Stick them with the pointy end,\" I think it was.", completion = "<Admiral Dvorek admires the polearms you present him.>\n\nOh, I'm sorry.  I was just imagining what these will look like with little bits of naga stuck to the ends of them.  Thank you, {name}.  We'll put these to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[25919] = { id = 25919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body Blows", description = "<Captain Taylor listens intently to your recount of Duarn and Nespirah's conversation.>\n\nI see.  So the creature wants our help waking it up, is that it?\n\nWith hundreds of slaves already picking away at her pearls, the beast seems to be a pretty heavy sleeper.  You might have better luck, though.\n\nMy suggestion?  Look around the creature's flesh for signs of weakness.  Maybe that weapon of yours will find a ticklish spot and force the beast to come to its senses.", sourceObjective = "Attack 7 Nespirah Abscesses along the walls of Nespirah's body chamber.", completion = "Hopefully we made some progress.  I'm not sure how we'll know when the creature wakes up, but something tells me that it will be pretty obvious when it does.", sourceObjectiveStatus = "unverified-source-field" }
quests[25920] = { id = 25920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Valuable", description = "My time in the pearl pits, however short, has made me curious about the naga's goals.  Yes, I now know that the naga want to use Nespirah as an engine of war, but if that's the case, then why are they enslaving men to mine her pearls?\n\nAssuming we escape this creature's hull, I would very much like to study these objects.  The pearls we found in the pits were much too large to carry, but I've seen the warlords and prophets occasionally carrying around smaller ones.", sourceObjective = "Obtain 5 Mysterious Pearls from Idra'kess Warlords and Idra'kess Prophets inside of Nespirah.", progress = "The naga must have some ulterior motive with these pearls.  If I had time to study them, I'm certain I could figure it out.", completion = "Brilliant work!\n\n<Valoren tucks the pearls away beneath her armor.>\n\nNow I just need you and Captain Taylor to get me safely out of here.  I can handle the studies from there on.", sourceObjectiveStatus = "unverified-source-field" }
quests[25921] = { id = 25921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overseer Idra'kess", description = "My men are flagging, {name}.  We won't last much longer against these naga, I'm afraid.  With the Idra'kess' weapons, and Nespirah's pearls, we should be ready to bust out of here.\n\nFollow the wall to the southeast, and look for a ramp to the upper chamber.  I assume their leader is in there, or perhaps the key to Nespirah's awakening.  Hopefully both.\n\nIf you feel strong enough, head up to the top of the shell and look for some answers.", sourceObjective = "Head to the top of Nespirah and slay Overseer Idra'kess.", completion = "No need to bring me up to speed... Nespirah has been narrating your adventures as they happened, and Captain Taylor filled me in on the rest.\n\n<Duarn closes his eyes and nods.>\n\nNespirah says that she is quite grateful, and that she has a small surprise ready for the naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[25922] = { id = 25922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking the Beast", description = "Thanks to you and the Captain, Nespirah has full control of her body... but most of the naga don't know this yet.  Once we make our escape, she will activate her biological defenses and destroy the naga from within.\n\nMake yourself ready... I will now tell Nespirah to begin the countdown.", sourceObjective = "Speak with Earthmender Duarn inside of Nespirah to activate her bio-defenses, then escape from Nespirah's body.", completion = "It appears that I owe you my life, yet again.  Thank the Light that you found me before you and your shaman activated those bio-defenses.", sourceObjectiveStatus = "unverified-source-field" }
quests[25923] = { id = 25923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish Nemesis", description = "Your turtle companion can use this newfound power to render the two of you invulnerable for a short period of time. You can \"turtle up\" to avoid the worst of Nemesis and his fury. To do so, simply invoke this totem.\n\nThis is all I can do for you. Together, you and a Child of Tortolla must defeat Nemesis, once and for all. Finish the Usurper!\n\nReturn to me if you lose your turtle friend.", sourceObjective = "Use the Totem of Tortolla and the help of a Child of Tortolla to defeat Nemesis. See Garunda Mountainpeak if you lose your turtle companion.", progress = "Is Nemesis dead?", completion = "The usurper has perished!\n\nTwilight's Hammer dreamed of creating their own pantheon of twisted ancients to rule over the land, sea, and air. With your help, they've all been executed.\n\nWe must tell Tortolla at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[25924] = { id = 25924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Duty", description = "Listen up, {race}!\n\nA new landmass has emerged off the coast of Eastern Kingdoms and we are engaged in a critical battle for control of the island!\n\nVictory there will leave Stormwind completely defenseless!\n\nNow is the time to strike!\n\nReport to the docks at once for transport to the battle.\n\nEvery warship is engaged, so you'll be boarding a mercenary vessel commissioned by the Warchief himself.", sourceObjective = "Ride the mercenary ship to battle.", completion = "Not exactly the battle you had anticipated, I'll wager. But a battle nonetheless, as you shall soon see....", sourceObjectiveStatus = "unverified-source-field" }
quests[25925] = { id = 25925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thal'darah's Vengeance", description = "We must attempt to establish communication with Farwatcher Glen, to the south. Our Darnassian glaive throwers are at your disposal, {name}. Use them to cut a swath through the encroaching Horde forces and clear a path to Farwatcher Glen.\n\nI only hope we're not too late to save the Glen. Should Farwatcher Glen be intact, find Hierophant Malyk and inform him of our status.", sourceObjective = "Kill 20 Horde soldiers and destroy 3 Krom'gar Demolishers in Battlescar Valley.", completion = "We witnessed the detonation of the bomb. Terrible, terrible destruction... Farwatcher Glen, for better or for worse, is still intact. Unfortunately we've nowhere to run.", sourceObjectiveStatus = "unverified-source-field" }
quests[25926] = { id = 25926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mired in Hatred", description = "The mirebeasts to the west are not my brethren... they are symptoms of the earth's disturbance, a foulness of rot given form.\n\nYou would not understand... they take the shape of my kind, infested within with decaying spores, forcing out flourished life in the swamp. They take all and leave only rot. Nothing left, nothing left!\n\nSoothe my mind, {race}. Slay the mirebeasts, cleanse the land, and perhaps my mind will settle.", sourceObjective = "Kill 10 Mouldering Mirebeasts.", completion = "Ahhh... yes. The swamp suffers less now.\n\nMore threats, though. More lurk. I can see them!", sourceObjectiveStatus = "unverified-source-field" }
quests[25927] = { id = 25927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Threat of Flame", description = "Flame has threatened me for far too long... far too long... but it is no longer the little ones, no longer mere gnats...\n\nThe fields burn! The hills and highlands scream, {race}, they scream. The elementals brought here consume all life in their wake.\n\nThey cannot stand, they cannot stand. Stop them. STOP THEM! Destroy the bringers of flame...", sourceObjective = "Kill 8 Rampant Fire Elementals.", completion = "Yes... the flames die. There is peace now. Peace for the land.", sourceObjectiveStatus = "unverified-source-field" }
quests[25928] = { id = 25928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortolla's Triumph", description = "I'll escort the children of Tortolla out of here and seal up this accursed portal.\n\nI'll leave it to you to inform Tortolla of our victory. Simply step back through the flamegate. The ancient will be pleased!", sourceObjective = "Step back through the flamegate and return to Tortolla at the Scorched Plain in Hyjal.", completion = "You've been to the firelands?\n\nNemesis is dead?\n\nSo it is finished.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25929] = { id = 25929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Legs", description = "Greetings, {class}. I am Erunak, a fellow survivor of this savagery.\n\nI'm afraid your travails have only just begun. The naga have been scouring these waters, attacking anyone that still lives.\n\nYou are not yet equipped to survive here, but I can remedy that.\n\nJust outside this ship live a special breed of starfish. Bring me some of them along with a conch shell. I'll prepare an enchantment that should help you grow accustomed to your environment.", sourceObjective = "Collect 3 Saltwater Starfish and a Conch Shell from the Sea Floor at Legion's Fate.", progress = "Were you able to gather the items I requested, {race}?", completion = "Here you are, {class}. With this you should find maneuvering in the sea to be nearly effortless. \n\nNow we must get to work. There is much to be done in little time.", sourceObjectiveStatus = "unverified-source-field" }
quests[25930] = { id = 25930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascending the Vale", description = "I am told that before the great upheaval the Charred Vale was a valley, closed off to the sea. One has merely to look to the south to see that the Charred Vale is no longer a valley and in fact has become an area of great volcanic activity.\n\nSalsbury here has configured a device that will allow us to ascend the volcano. Use it to get to the top and assess the goings on.\n\nI will keep in touch with this Gnomecorder device, which Salsbury has so kindly gifted upon me.", sourceObjective = "Use Salsbury's Rocket Pack to ascend the Charred Vale's volcano.", completion = "<The Gnomecorder crackles with energy.>\n\nI say, are you there, {name}? It would appear that you are in the center of a dragon's lair.", sourceObjectiveStatus = "unverified-source-field" }
quests[25931] = { id = 25931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brood of Seldarria", description = "<The Gnomecorder buzzes.>\n\nBe very careful, {name}. You do not want to rouse that black dragon.\n\nNow, look around you. If this is a nest then there must be black dragon eggs nearby. Search the premises for eggs and destroy any that you see.\n\nReturn to me should you find and destroy Seldarria's eggs.\n\nGoldrinn watch over you.", sourceObjective = "Destroy 5 of Seldarria's Eggs.", completion = "A smashing success! Perhaps only a minor victory against the brood of Deathwing, but a victory nonetheless!", sourceObjectiveStatus = "unverified-source-field" }
quests[25932] = { id = 25932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Raid Night Every Night", description = "The reports I'm sending Captain Tharran can't really convey the amount of trouble the Frostmanes have created for us. Your assault on the village has started to relieve some of the pressure. The raids are still frequent, but the trolls don't have the numbers they once did.\n\nEven so, my men are tired and their morale is flagging. Would you help us keep watch for the Frostmane raiders? They could turn up at any time.", sourceObjective = "Help Sergeant Flinthammer and his mountaineers defend Amberstill Ranch from Frostmane Raiders.", progress = "We're glad to have your help, {name}.", completion = "With your help, we've managed to weaken the raiders considerably. They haven't suffered such losses since the raids began. Now is the time to press our advantage.", sourceObjectiveStatus = "unverified-source-field" }
quests[25933] = { id = 25933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help for the Quarry", description = "Thank you again for all your help here, {name}.\n\nI have a cousin who used to work in the mines beneath the Gol'Bolar Quarry, but he hasn't been able to work since troggs flooded into the mines and took control. The quarry and its camp are just to the southeast of the ranch. Would you be willing to check in with the foreman there and see if there's anything to be done?", sourceObjective = "Speak to Foreman Stonebrow at the Gol'Bolar Quarry.", completion = "Sergeant Flinthammer? I'm not familiar with the name, but, aye, there is a Flinthammer among the miners. He's one of the ones lucky enough to make it out of the mine, but most of my men are still trapped down there.", sourceObjectiveStatus = "unverified-source-field" }
quests[25934] = { id = 25934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World First: Gnomegen", description = "Good day, citizen, allow me to introduce myself. I am Salsbury, soon to be the world's first gnomegen. Malyk has assured me that as soon as my work here is complete he will grant me the gift of the worgen.\n\nSo with the introduction out of the way, I've a request!\n\nWithin the Charred Vale, south of here, roam newly created fire elementals. I desperately need a rare blazing heart of fire from one of the fiends. Get it for me and you bring me one step closer to becoming a gnomegen!", sourceObjective = "Collect 1 Blazing Heart of Fire.", progress = "Have you recovered the blazing heart of fire?", completion = "Excellent. This will allow me to finish my last task and hopefully gain the form of the wolf!\n\n<Salsbury howls.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25935] = { id = 25935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry Pups", description = "Ah, a new arrival! Good that you're here <lad/lass>! The pups are hungry and we're completely out of food.\n\nThankfully they love dragon meat, which fortuitously exists in abundance within the Charred Vale, south of here.\n\nBe a good <boy/girl> and fetch me several pounds of black dragon whelp filet.", sourceObjective = "Collect 6 Black Dragon Whelp Filets.", progress = "Hurry, {name}, the pups are hungry!", completion = "Excellent. The dogs will be well fed and ready to defend our outpost for weeks!", sourceObjectiveStatus = "unverified-source-field" }
quests[25936] = { id = 25936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pay It Forward", description = "You are now able to move about this realm more freely and without fear of drowning.\n\nThis is where our work begins.\n\nFirst, you have many allies nearby who are drowning as we speak. As I saved you, you must save them.\n\nI have enchanted the shell you brought me. Use it to rescue your friends.\n\nHurry now!", sourceObjective = "Use the Enchanted Conch to rescue 6 Drowning Warriors.", progress = "Were you able to rescue the warriors, {race}?\n\nWe will perish without their help...", completion = "While you were away, I was able to revive some of the fallen warriors.\n\nWe'll need every hand if we are to survive here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25937] = { id = 25937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priceless Treasures", description = "Mining wasn't the only thing going on in the quarry, you know. I led a team of Explorers' League excavators recovering priceless ancient artifacts.\n\nI managed to escape, but my colleagues were much deeper in the mine and didn't survive the initial trogg attack.\n\nThey took great pride in their work and they risked their lives to learn more of our history. If you're going into the mines, take this pick with you and see if you can find anything in the digs the prospectors started.", sourceObjective = "Recover 8 Frozen Artifacts from inside the Gol'Bolar Quarry Mine.", progress = "Were you able to find any artifacts down there?", completion = "Thank you for recovering these artifacts. I will see to it that they are displayed in the Ironforge museum along with the story of those who died to recover them.", sourceObjectiveStatus = "unverified-source-field" }
quests[25938] = { id = 25938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help for Desolace", description = "I've received a disturbing message from Nijel's Point in Desolace. It would seem as if the great upheaval has created some new problems for them, which they are ill-equipped to handle. I was given no further information.\n\nReport to Office Jankie in Desolace. She will direct you to Nijel's Point.\n\nGood luck, {name}.", sourceObjective = "Report to Officer Jankie at Tethris Aran in Desolace.", completion = "Hold there, stranger!", sourceObjectiveStatus = "unverified-source-field" }
quests[25939] = { id = 25939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Peat's Sake", description = "The elementals rampaging across Direforge Hill are setting the very land beneath them ablaze. In a marsh such as this, fire can find many places to smoulder through the deep moss and peat.\n\nYou must quench the fires before they spread further. Take this flower... blessed by nature's rain, it will let you douse the fires.\n\nThe blossom may also prove useful against the elementals themselves.", sourceObjective = "Use the Blessed Floodlily to extinguish 7 Marsh Fires.", completion = "In sparing the land further suffering, you've also helped us soothe the greenwarden.\n\nMany thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25940] = { id = 25940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Stand at Whistling Grove", description = "We might have a chance to beat these flames back thanks to your work in the Inferno.\n\nStill, more wildlife is threatened. Keeper Taldros ran north through the flames, to Whistling Grove.\n\nSee if you can help him!", sourceObjective = "Report to Keeper Taldros at Whistling Grove in Mount Hyjal.", completion = "The forest is being devoured!", sourceObjectiveStatus = "unverified-source-field" }
quests[25941] = { id = 25941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rest For the Weary", description = "You have done well, {race}, but there is much more to do and I grow weary.\n\nI have expended a great deal of energy sending a distress message to Earthen Ring leadership, pleading for their help.\n\nI must rest if I am to be of further use to us here.\n\nSpeak to the leader of the men you've saved and do what you can to help them prepare for battle.\n\nThe naga are scouring the waters for us. It is but a matter of time before they return - and they will surely come in even greater force.", sourceObjective = "Speak to Legionnaire Nazgrim.", completion = "I hear you, {race}.\n\nI understand the urgency, but these men are in no condition to fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[25942] = { id = 25942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buy Us Some Time", description = "Many good warriors have been lost today.\n\nIf what the shaman says is true, then we must act swiftly or we will add to their numbers.\n\nThe naga are out there, scouring these waters looking for survivors.\n\nWe are not yet ready to fight, {race}. You must buy us time to make preparations.\n\nFind the naga that hunt us and delay their efforts.", sourceObjective = "Kill 8 Zin'jatar Raiders at Legion's Fate.", progress = "You give those scaly scum something to think about, {race}?", completion = "Let us hope that your work has bought us the time we need...", sourceObjectiveStatus = "unverified-source-field" }
quests[25943] = { id = 25943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traveling on Our Stomachs", description = "I'll need your help if I am to get these orcs ready for battle.\n\nAny worthy leader knows that his warriors travel and fight on their stomachs. No food, no victory.\n\nThese warriors are weary from their struggle out there. They need food before they're ready to overcome a naga attack.\n\nSpeaking of traveling on stomachs, I saw plenty of crabs out on the sea floor...", sourceObjective = "Collect 8 Succulent Crab Meat from Splitclaw Skitterers.", progress = "You got food for the troops, {race}?", completion = "Good grub.\n\nSoon we'll be back to fighting strength.", sourceObjectiveStatus = "unverified-source-field" }
quests[25944] = { id = 25944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Girding Our Loins", description = "As we struggled not to drown, my orcs and I were forced to abandon our weapons and much of our armor.\n\nErunak says to expect a major attack from the naga soon and I believe him.\n\nIf we're going to be victorious, we'll need your help to recover our lost equipment.\n\nYou should find it scattered around the sea floor near our shipwrecks here and to the north.\n\nMake haste, {race}. The enemy could arrive at any moment.", sourceObjective = "Collect 5 Orgrimmar Axes, 5 Orgrimmar Breastplates and 5 Orgrimmar Helms from the sea floor and from Gilblin Plunderers in Legion's Fate.", progress = "Were you able to gather up our gear, {race}?", completion = "You have done well, {race}.\n\nOur chances of survival are increasing.", sourceObjectiveStatus = "unverified-source-field" }
quests[25945] = { id = 25945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Here to Do One Thing, Maybe Two...", description = "You're in Hellscream's army now, {name}, and in Hellscream's army we kick butt and take names. Gone are the days of our people starving in the streets of Orgrimmar as we sign treaties with elves. We take what we need now. Kalimdor belongs to the Horde!\n\nThe Alliance attempts to stop our expansion every chance they get. Unsatisfied with owning most of the Eastern Kingdoms, those pig-lickers want it all!\n\nOverlord Krom'gar has called for more troops in Stonetalon. Get on the caravan west of here and go!", sourceObjective = "Take the Krom'gar Wagon to the Fold in Stonetalon Mountains.", completion = "While you remain in Stonetalon and fight as a Krom'gar soldier you will remain suited up! Am I clear? DO you hear me, grunt? If I see you without Hellscream's beloved tabard I will put my foot so far up your backside that you'll be spitting up laces.", sourceObjectiveStatus = "unverified-source-field" }
quests[25946] = { id = 25946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helm's Deep", description = "This helm and its associated components are marked with the seal of Stormwind. It was no doubt cast off from an Alliance ship that suffered a similar fate to yours.\n\nLooking closer, this seems far too intricate and sturdy to be everyday diving equipment. Perhaps Nazgrim can make some sense of this...", sourceObjective = "Take the Alliance S.E.A.L. Equipment to Legionnaire Nazgrim at The Immortal Coil.\n\nProvided item:", completion = "Blood and Thunder!\n\nThis changes everything, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25947] = { id = 25947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finders, Keepers", description = "I recognize this helm, {race}. You were wise to bring it to me.\n\nThe Alliance have a special unit, trained and equipped to explore and fight beneath the sea.\n\nIt would seem that they are in this region to do more than just defend against our attack.\n\nThere must be more of these down here, and if you can find them it could turn things around for the Vanguard.", sourceObjective = "Gather 5 pieces of Stormwind S.E.A.L. Equipment.", progress = "Were you able to locate more of the Alliance gear, {name}?", completion = "Well done!\n\nNow, more than ever, we are prepared to face the naga!", sourceObjectiveStatus = "unverified-source-field" }
quests[25948] = { id = 25948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring It On!", description = "It is time, {class}.\n\nWe are as ready as we ever will be!\n\nI shall address the Vanguard, and then we shall swim into the sea to meet our fate.", sourceObjective = "Speak with Legionnaire Nazgrim aboard the Immortal Coil.", completion = "No time to address the Vanguard.\n\nJust as well...", sourceObjectiveStatus = "unverified-source-field" }
quests[25949] = { id = 25949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood and Thunder!", description = "The time has come to make our stand, {race}.\n\nWe'll defend this ship to our last breath, and make these naga scum think twice before approaching it again!\n\nFor the Horde!", sourceObjective = "Assist Legionnaire Nazgrim in the defense of The Immortal Coil.", completion = "The Earthen Ring has received my distress message and sent help - just in time it would seem.\n\nHopefully more can be sent soon. We are but few against a great many.", sourceObjectiveStatus = "unverified-source-field" }
quests[25950] = { id = 25950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sira'kess Slaying", description = "You're the {name} everyone's been talking about? Good to meet ya, love. Let's have a butcher's hook.\n\nWell, enough rabbit, right? Let's get down to it. I need you to swim out northwest to the Sira'kess Front and read and write them snakes something quick.\n\nNothing fancy. They're looking for a bother, and we'll give 'em a right good one in the ol' boat race.", sourceObjective = "Slay 10 Sira'kess Naga.", completion = "Chicken and rice, {name}! That will show those sorry and sad snakes who's the ol' pitch and toss!\n\nNow it's bird lime for that tiddlywink. Finger and thumb or plink plonk?", sourceObjectiveStatus = "unverified-source-field" }
quests[25951] = { id = 25951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Judgement", description = "Get to the bridge on the east, quickly. Lady Naz'jar and the Fathom-Lord should be there with whatever forces remain.\n\nFollow our Lady's direction, as always. Hold the bridge until we can complete the ritual.\n\nOnce our allies arrive, the Kvaldir will be doomed.", sourceObjective = "Hold the bridge on Quel'Dormir Terrace until Lady Sira'kess' allies arrive.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "Stand with us, Battlemaiden. We shall not fall this day.", completion = "I could ask for no more proficient a Battlemaiden than you. You have done yourself a great honor this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[25952] = { id = 25952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught Off-Guard", description = "Our escape from the shell can't have gone unnoticed, but either the naga at these ruins weren't informed or they don't consider us a threat. I don't intend to take the opportunity for granted - we strike now.\n\nI need you to slip into the lower level of the ruins to our west and take out as many of their patrols as you can. We cannot risk any of those patrols finding out about our occupation of this cave - make sure none escape.", sourceObjective = "Kill 10 Azsh'ir Patrollers.", completion = "Excellent work, {class}.\n\nI will get some patrols out of our own to make sure that no more naga get within sight of this cave. We should have the area secured within the hour.", sourceObjectiveStatus = "unverified-source-field" }
quests[25953] = { id = 25953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Approach", description = "I've taken the liberty of performing some preliminary scouting. The naga may not be aware of our position, but they are not entirely unprepared for intruders.\n\nBeyond their patrols, they have set up magical sentry devices that will warn them of unwelcome guests. Fortunately, they seem to have sacrificed quality for quantity, and there is definitely a window in which the devices can be destroyed before their alarms are answered.\n\nI trust that you can see to this before our other soldiers arrive.", sourceObjective = "Destroy 8 Azsh'ir Monitors.", completion = "Well done, {name}, and just in time too. The Captain just started sending more men out. Strong axe arms, but I doubt they possess quite the same awareness and finesse that you do.\n\nWe were lucky to have you here when things went south. I suspect you will have a large role to play in things to come as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[25954] = { id = 25954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Occupation of Time", description = "Look--{name} is it?--I need your help. I know most everyone in this cave thinks that we're not in a position to be worrying about anything but our own hides right now, but I cannot dismiss my ancestors so readily.\n\nThis was one of the royal cities of the elves in the days when Azshara was queen. In this city lie the keys to lore long lost and artifacts of unimaginable historical value. All I want from you, while you're out in the city proper, is to keep a watchful eye out for objects of significance.", sourceObjective = "Investigate the 4 intact statues in the Vashj'ir Gardens.", completion = "Thank you so much for taking this seriously.\n\nThis is some of the first definitive proof of other members of the Vashj family. Very interesting. And I'd never even heard of either of the other two figures you mentioned until now.\n\nSo much of our history was lost during the sundering - it's exciting to have a chance at reclaiming some of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[25955] = { id = 25955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Better Vantage", description = "This cave is our only refuge. There's no help on the way. Whatever happens, this cave must remain safe or we are all sure to die down here.\n\nWe need a forward post to launch our attacks from. Something defensible.\n\nIn the eastern portion of the ruins on the lowest level, scout the north end of the gardens, the passage leading under the main structure just west of the gardens, and the cluster of buildings at the southeast corner of the ruins, under the bridges.\n\nBring me back any information you can.", sourceObjective = "On the lowest level of the ruins, scout the northern end of the Quel'Dormir Gardens, the passage that leads under the ruins west of the gardens, and the structures at the southeast corner of the ruins, below the bridges.", completion = "This is good intel. You have a sharp eye, {class}.\n\nIt sounds like the building north of the gardens will make a suitable forward post. I will send some men immediately to start defensive preparations and we will reposition there as soon as possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[25956] = { id = 25956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upon the Scene of Battle", description = "All around you lie the remnants of a fierce battle. The naga skeletons are no surprise, but the weapons and remains of their apparent opponents are somewhat more unexpected.\n\nAmidst the bones, you spot a strangely prominent piece of metal jutting out from one of the skulls. It's difficult to tell what sort of weapon it might have once been part of, but it stands out sufficiently to prompt you to retrieve it as evidence.\n\nSurely someone back at the cave would be interested in this revelation.", sourceObjective = "Bring the broken shard back to the Legion's Rest.", progress = "Yes, {class}?", completion = "A shard of metal?\n\nThe remains you describe sound much like the sea vrykul we encountered in Northrend. We'll not be striking any alliances with their sort, no matter the cause. Still, this information may prove useful in the future.\n\nI will think on it further if time permits. Thank you for bringing it to my attention.", sourceObjectiveStatus = "unverified-source-field" }
quests[25957] = { id = 25957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: The Invasion of Vashj'ir", description = "The shard you recovered looks to be of naga origin. I had hoped to find a strong focal object like this for a spell I've been working on that would allow us to glimpse into the recent past.\n\nI've enchanted the blade, but you'll have to take it to a place where we know its owner was. I want you to travel back to the site where you found it and use the blade.\n\nPerhaps we can uncover more behind what the naga are doing here. Or even better, maybe we'll uncover a weakness that will give us a better chance.", sourceObjective = "Use the Blade of the Naz'jar Battlemaiden at the battle site at the southeast end of the ruins.", completion = "A Battlemaiden? I never heard of such a thing.\n\nThe way you explain it, it sounds like the naga forces are far greater in scope than the Captain could possibly have realized. We might be able to learn more through the blade if we can find other locations where this Battlemaiden was present, but the information you gave me makes me fear for the captain and his soldiers. We must warn them.", sourceObjectiveStatus = "unverified-source-field" }
quests[25958] = { id = 25958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking Forward", description = "The Captain used the information you gathered for him to make a forward post under the terrace to our west. He's been preparing there for some kind of attack against the naga.\n\nYou should go to him immediately and inform him of the scope of what you've witnessed. Our force is small, and I fear for our soldiers if we charge in too recklessly.\n\nTake my sea horse. It knows the way.", sourceObjective = "Find and speak to Captain Vilethorn north of the Quel'Dormir Gardens.\n\nUse Wavespeaker Tulra's sea horse to reach the forward post quickly.", completion = "Good to see you again, {class}. I almost thought we'd lost you to the Wavespeaker's fool errand.\n\nDid anything come of it?", sourceObjectiveStatus = "unverified-source-field" }
quests[25959] = { id = 25959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear Goals", description = "I see. The news you bring is grim, but I was not entirely unprepared for such possibilities. Without any effective scouting of naga numbers, I knew our plan was risky, but that's why we established this forward post.\n\nLet me put it to you plainly, {class}. If we do not keep the naga off-balance, they will bring the fight to us. We do not have the structures or the men to mount a defense, so that is not an option.\n\nWe need more time. Can you thin their numbers to the south, under the far terrace?", sourceObjective = "Kill 10 of the naga forces building up on the ground level, under the southwestern terrace.", completion = "More naga are amassing to the south than reported too it seems. We shall have to move quickly then.", sourceObjectiveStatus = "unverified-source-field" }
quests[25960] = { id = 25960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Entirely Unprepared", description = "I overheard your conversation with the Captain. I know what we're doing sounds insane, but we really don't have much choice. There are people back at that cave that are depending on us.\n\nI've stationed lookouts on various ledges in the immediate area. They're burning ammo fast on the scattered naga scouts. Bring them more crossbow bolts to buy us some extra time.", sourceObjective = "Deliver 8 Bundles of Crossbow Bolts to Horde Lookouts on ledges around the north end of Quel'Dormir Gardens.", progress = "Finished already?", completion = "You are perhaps the most dependable {race} I've ever met. I wish I could have more men that showed half as much pride as you do.", sourceObjectiveStatus = "unverified-source-field" }
quests[25962] = { id = 25962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Properly Inspired", description = "Been all over the place. Blown all kinds of things up. I thought I might have some trouble carrying on the trend, what with the water and all, but it's all just a matter of inspiration.\n\nI found something volatile enough to make bombs out of! There's a bunch of kelp hanging under the terrace to the southwest. Normally kelp stores gas that makes it float - this kelp produces a different kind of heavy gas. It keeps it hanging, but also makes for great explosions.\n\nGather me some?", sourceObjective = "Gather 8 Bloated Kelp Bulbs hanging under the southwestern terrace.", progress = "Tick, tock, tick, tock. Always in such a hurry. No time for innovation. What I wouldn't give for a lab again!", completion = "You are brave indeed! I've seen you battling all manner of murloc, naga, and pointy-toothed fish, but that was nothing! The way you just sling those kelp bulbs under your arm like that is a whole new kind of fearless. BOOM! You could blow up at any second.\n\nYou're my kind of {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25963] = { id = 25963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Action", description = "We have everything we need to begin the attack.\n\nIf your claims were correct, you would do well to make sure you cling tight to your mount as we make the run. Anyone who gets caught in the open water isn't likely to out-swim a naga.\n\nKill as many as you can as we make the attack run and we'll rendezvous on the broken ledge of the southern terrace above once we've expended our explosives. Hopefully by that point there will be few enough that we can finish them off the old-fashioned way.", sourceObjective = "Speak to Fiasco Sizzlegrin just outside of the building to join the assault, then use your improvised explosives to kill 100 Azsh'ir Soldiers, 20 Azsh'ir Wave Screamers, and 12 Azsh'ir Archaens.", completion = "You did great up there, soldier! You devastated their ranks, but there were far more than we accounted for, and most of my men went down out there in the masses of naga.\n\nWe'll need to hold this position as long as possible to buy them time. Hopefully some of them will still make it to the rendezvous.", sourceObjectiveStatus = "unverified-source-field" }
quests[25964] = { id = 25964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen But Not Forgotten", description = "That was a disaster! Most of our men went down to spears before making it anywhere near the rendezvous.\n\nWe're only going to be able to hold this position for so long before the naga overrun us. We need to get out there to the southwest and save as many of the men as we can find - do anything you can.\n\nThey won't last long. Please hurry!", sourceObjective = "Rescue 6 Injured Assault Volunteers.", progress = "These guys aren't in good shape. We may need to retreat sooner than we'd like.", completion = "Thank you. Truly.\n\nWe need to get these men moving as soon as possible. I'll meet you back at the forward post soon, I'm sure.", sourceObjectiveStatus = "unverified-source-field" }
quests[25965] = { id = 25965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gauging Success", description = "Vicious louts... they did a lot of damage with those spears.\n\n<The captain winces slightly as he clutches a wound on his side.>\n\nWe'll hold here as long as we can for all the men to make it. I need someone to scout their numbers to see how much damage we did.\n\nOne of the biggest groups of them was around the corner on the northwest portion of this round terrace, and the other was a bit farther to the north in the small tunnel, also on this middle level of the ruins.\n\nUp for some scouting?", sourceObjective = "Scout the northwestern portion of the circular terrace and the tunnel under the main stairs to the north. Both locations are on Nar'shola Terrace, the middle level of the ruins.", progress = "Any word... on their numbers?", completion = "Still so many? They must want something very important here to come in such numbers.\n\nI will be honest with you, {name}, because you deserve at least that: I don't know how much hope there is. We will retreat shortly, but we won't be able to defend ourselves when they strike back. We don't have anywhere to run... we're running out of options.\n\nI'm sorry, I should keep such thoughts to myself. Do me a favor and don't mention any of that to the men. I'll figure something out.", sourceObjectiveStatus = "unverified-source-field" }
quests[25966] = { id = 25966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: The Slaughter of Biel'aran Ridge", description = "Look, I know this is asking a lot during a time like this, but I need you to tear yourself away from this defeat for a moment.\n\nI will tend to these soldiers - you need to find the location of that battle with the Kvaldir General to the west that you told me about. You should be able to glimpse more of the Battlemaiden's experiences from there. I have a strong feeling that the key to defeating these naga will lie with that Battlemaiden.\n\nPlease hurry - I will do everything I can to buy you time.", sourceObjective = "Witness the continuing story of the Battlemaiden by using her broken blade at the site of the Kvaldir General's death.", completion = "You're finished! Just in time. I don't think we could have held them much longer.\n\nAn artifact? Could this be something we can use against the naga? I suppose that would require finding it.\n\nWe may have to attend to more pressing matters first, until an opportunity to pursue this further presents itself.", sourceObjectiveStatus = "unverified-source-field" }
quests[25967] = { id = 25967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Ground", description = "You'll have to catch me up more later. Right now, we need to get out of here before more naga push in. Make your way back to the forward post on the level below us.\n\nTake my sea horse. We will meet you back there shortly.", sourceObjective = "Use Wavespeaker Tulra's sea horse to return to Captain Vilethorn just north of the Quel'Dormir Gardens.", completion = "You made it! After the attack at the forward post, I thought we might be the only ones left. It's good to see you in one piece, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25968] = { id = 25968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Plan", description = "Toldrek and Fiasco left to find a way to contact help. The trade lanes aren't far, so there might be a chance of success, but I'm wary to let anyone get their hopes up.\n\nIn truth, we don't have any other options. We're not likely to last much longer here. The naga will find us eventually, and... well... you saw how many of them there were.\n\nYou should go find the two of them on Biel'aran Ridge to the southeast. I'll keep everyone here safe as long as I can.", sourceObjective = "Meet with Fiasco Sizzlegrin on Biel'aran Ridge.", completion = "Look at you, a regular aquatic hero! Trouble comes. You come. Save the day.  You must be proud of yourself!\n\nWe've devised our brilliant plan. Gloriously simple, barring the hostility of local life. Simpler yet with a you available!", sourceObjectiveStatus = "unverified-source-field" }
quests[25969] = { id = 25969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostile Waters", description = "Fiasco came out here with a balloon of some sort that he retrieved from one of our ships. He tried to float it to the top, but those Muckskin Scroungers came out of nowhere and swarmed the thing.\n\nHe's got an idea for another balloon, but we need to make sure that the past doesn't repeat itself. I need you to kill off those giblins. Or at the very least, enough of them to make them fear us.", sourceObjective = "Kill 10 Muckskin Scroungers.", progress = "These scroungers seem intensely curious about our equipment. Sometimes suicidally so. I wonder what attracts them to it so much.", completion = "Less gilblins is good.\n\nI'm glad that they're so primitive. I don't think I'd want to be dealing with a race of aquatic tech-freaks right now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25970] = { id = 25970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come Prepared", description = "It's a short swim to the top. Not much trouble really. Hard to get any supplies up there though. Too heavy.\n\nAll of the ships in all of the Horde fleets stow a survival kit. I had a balloon from the old survival kit, but it fell on hard times recently. I need another survival kit.\n\nThere's a ship to the southeastish. Let's hope that the survivors were dumb and didn't take the survival kit. More survival kit for us.", sourceObjective = "Retrieve a Horde Survival Kit.", progress = "A whole big box of amazing! That's what it is. I need more amazing in my life.\n\nDon't worry, I'll share.", completion = "Let me see, let me see... flare gun... balloon... no rope. Never any rope. Terribly impractical if you do ask me. Rope should be mandatory.", sourceObjectiveStatus = "unverified-source-field" }
quests[25971] = { id = 25971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfurling Plan", description = "Survival kits never have any rope. It makes no sense! Rope and bombs, that's all they should store. The rest of this stuff is just a waste of space.\n\nExcept maybe the balloon. That's coming in handy right now.\n\nI bet those Kvaldir have rope. They're always riding around in boats, tying knots, dressing in nets. Go take some rope from them! I must have it for our plan to work. It is non-optional.", sourceObjective = "Collect 8 Coils of Kvaldir Rope.", progress = "The rope ties the whole plan together!", completion = "This is great! I love it. It should work per... ewww! Is this stuff braided with hair?\n\nDoesn't matter. Almost done. This thing will be ready in the twist of a rope.", sourceObjectiveStatus = "unverified-source-field" }
quests[25972] = { id = 25972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor and Privilege", description = "All done! I'm confident it will work. And not a scrounger in sight to pop a hole in it this time! Well played.\n\nToldrek already swam up to catch it, all concerned about currents and what not. He said you'd get the honors though. Nice guy - don't know how he lasts.\n\nGo to the top with the balloon, take the flare gun from the crate, and scan the horizon for Horde ships. If you see any, fire the flare towards them. That's it! All there is to it.\n\nSwim. Float. Flare. Rescue! That last part's my favorite.", sourceObjective = "Swim to the surface, retrieve the flare gun, and fire a rescue flare towards the Horde Ships.", progress = "Those aren't trade ships, those are war ships. Still, this is an incredible stroke of luck. Fire that flare off and pray that they see it.", completion = "Perfect! There's no way they missed that, fighting or not.", sourceObjectiveStatus = "unverified-source-field" }
quests[25973] = { id = 25973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome News", description = "They'll probably send a skiff over, which may take a bit. I'll stay here to make contact.\n\nYou need to return to the cave immediately and let them know that rescue is on its way. We can only hope that the naga have not found them yet.\n\nGo. Swim fast, {name}.", sourceObjective = "Return to Legionnaire Nazgrim at Legion's Rest.", completion = "That is the best news I've ever heard. We'll get the survivors moving over there to the surface as soon as possible. Perhaps we can forget that this whole nightmare ever happened.\n\nThank you, {name}. You've shown your worth down here. There will be a glorious spot in the Horde for you.\n\nYou should consider meeting us at the ships later, when you finish saying your goodbyes to the naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[25974] = { id = 25974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sira'kess Slaying", description = "So, you're the {name} everyone's been talking about? It's good to finally meet you.\n\nWell, enough talk, right? Let's get down to it. I need you to swim out northwest to the Sira'kess Front and kill those naga real quick.\n\nNothing fancy. They're looking for a fight, and we'll give them one! Well, you will.", sourceObjective = "Slay 10 Sira'kess Naga.", completion = "Nice, {name}! That will show those naga who's the boss!\n\nNow it's time for that drink. You want rum or wine?", sourceObjectiveStatus = "unverified-source-field" }
quests[25975] = { id = 25975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Reclamation", description = "We've got our reinforcements, but we still need to find a way to pay them. That kind of action doesn't come cheap.\n\nUp on Deepfin Ridge to the northwest, the slimy gilblin have stolen all sorts of treasure. I think that it's time to reclaim some of it for the cause.", sourceObjective = "Collect 6 Deepfin Plunder.", progress = "How much plunder have you managed to reclaim, {name}?", completion = "That should be enough for now. We know where there's more should the need arise.", sourceObjectiveStatus = "unverified-source-field" }
quests[25976] = { id = 25976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Reclamation", description = "Blood and thunder! We have our reinforcements, but they still need to be paid. They won't be cheap.\n\nUp on Deepfin Ridge to the northwest, the slimy gilblin have stolen all sorts of treasure. It's time to reclaim some of it for the Horde.\n\nHellscream's eyes are upon you, {name}!", sourceObjective = "Collect 6 Deepfin Plunder.", progress = "How much plunder did you get, {name}?", completion = "That's a lot! And we know where there's more should the need arise.", sourceObjectiveStatus = "unverified-source-field" }
quests[25977] = { id = 25977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Standard Day for Azrajar", description = "{name}, the snakes are after our daft and barmy. Go back northwest to Deepfin Ridge and plant some do me good in that pot and pan pitch and toss of theirs.\n\nThey'll kick and prance away with their alderman's nails tucked between their nutmegs when they see that. Not that they've got any nutmegs mind you.", sourceObjective = "Plant the Alliance Standard in Fathom-Caller Azrajar's corpse.", completion = "Nice Uncle Bob of pokin' their general.\n\n<The lieutenant shakes her head and grins.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25978] = { id = 25978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entombed in Ice", description = "Khurgorn tells me the cataclysm upset the balance of the elements all over the world. Helm's Bed Lake, to the south, used to be beautiful and tranquil, but it is now overrun with agitated water elementals. When they started to leave the confines of the lake, I sent my troops in to keep them busy, but most have been frozen in blocks of ice.\n\nIf we can break them free, they have a good chance of recovering. I cannot spare the men for a second expedition out onto the lake. Would you be willing to try?", sourceObjective = "Break open six Icy Tombs to free the Frozen Mountaineers trapped inside at Helm's Bed Lake.", completion = "You've done it! The mountaineers are returning to camp and our medics will have their hands full. We are all in your debt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25979] = { id = 25979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing with the Surge", description = "The elements are in turmoil, {class}. The cataclysm stirred up the long-dormant water spirits of Helm's Bed Lake, just to the south. They're angry, confused, and unwilling to hear my pleas.\n\nI have tried everything I know to calm them, to persuade them to stop lashing out and attacking the sergeant's mountaineers.\n\nIt pains me to say this, but no other options remain -- we must kill the elementals.", sourceObjective = "Kill 6 Helm's Bed Surgers at Helm's Bed Lake.", completion = "It is never easy to countenance violence against the very elements whose powers I wield, but sometimes there is no other solution. Our duty to the people of Dun Morogh comes first.", sourceObjectiveStatus = "unverified-source-field" }
quests[25980] = { id = 25980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Standard Day for Azrajar", description = "{name}, the naga are after our forces. I need you to go back northwest to Deepfin Ridge and stick our standard in their general, Fathom-Caller Azrajar.\n\nThey'll swim away with their tails tucked between their... er. Well, I guess they don't have any legs, now do they?", sourceObjective = "Plant the Horde Standard in Fathom-Caller Azrajar's corpse.", completion = "Stuck him right through, did you? I would have loved to have seen that!", sourceObjectiveStatus = "unverified-source-field" }
quests[25981] = { id = 25981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Aren't Masks", description = "{name}, there are these demon squid-things out there that are eating gilblins' heads and then taking them over! That's one way to get slaves.\n\nThink you could swim out northwest onto Deepfin Ridge or into the Sira'kess Front and bring me back some of those Merciless things?", sourceObjective = "Collect 6 Merciless Heads.", progress = "How many you got?", completion = "Ah, they're ugly, but they mostly look harmless. Smelly though.\n\nHere, let me clean the gilblin stuff out of these. I've got an idea....", sourceObjectiveStatus = "unverified-source-field" }
quests[25982] = { id = 25982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Aren't Masks", description = "{name}, there are demon squids out there that are eating gilblins' heads and then taking them over! They better not come in here!\n\nThink you could swim out northwest onto Deepfin Ridge or into the Sira'kess Front and bring me back some of those Merciless things? Preferably dead, I think.", sourceObjective = "Collect 6 Merciless Heads.", progress = "What's that smell?", completion = "Ah, they're ugly, but they mostly look harmless. Mostly. They're almost cute in a way.\n\nHere, let me clean the gilblin stuff out of these. I've got an idea....", sourceObjectiveStatus = "unverified-source-field" }
quests[25983] = { id = 25983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Promontory Point", description = "We need to get this information up to Captain Taylor on Promontory Point! He's out there to the northwest with Erunak Stonespeaker and the Earthen Ring.", sourceObjective = "Speak with Captain Taylor on Promontory Point in Vashj'ir.", completion = "That's very disturbing news, but I believe our Earthen Ring friends here have a plan.\n\nAnd now that you're here....", sourceObjectiveStatus = "unverified-source-field" }
quests[25984] = { id = 25984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Promontory Point", description = "{name}, I need you to get this information to Legionnaire Nazgrim on Promontory Point. He's up there to the northwest with Erunak Stonespeaker and those Earthen Ring people.", sourceObjective = "Speak with Legionnaire Nazgrim on Promontory Point in Vashj'ir.", completion = "If it weren't you saying it, I wouldn't believe what that troublesome goblin has to say. This is troubling indeed, but I think our Earthen Ring friends have a few ideas.\n\nAnd now that you're here....", sourceObjectiveStatus = "unverified-source-field" }
quests[25985] = { id = 25985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wings Over Mount Hyjal", description = "{name}, is it true you're going to try to commune with the ancients?\n\nSouthwest of here is the Shrine of Aviana, the matron of all flying creatures. It's the home of my favorite instructor, Choluna. I've never encountered one who was so deeply in touch with the spirits of this world. You could learn a lot from her!\n\nThe recent attacks have isolated the shrine. But it's easily accessible from the air - look for the second biggest tree on Hyjal. Good luck!", sourceObjective = "Locate Choluna at the Shrine of Aviana in Mount Hyjal.", completion = "Oh, you were sent here by Tiala? A wonderful student, she'll do many great things.\n\nAlthough I sense even greater potential from you.\n\nPlease, stay a while in our shrine. There's much to do, but you can't accomplish anything with a troubled mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25986] = { id = 25986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Lake", description = "You've been a great help in securing the mines and rescuing the trapped miners.\n\nThe Senate will be heartened to hear that you and Captain Tharran's mountaineers have made progress in securing Dun Morogh.\n\nWhat worries me is that I haven't seen any reports from Sergeant Bahrum and his detachment. They were sent east, along the road toward Helm's Bed Lake, and ordered to set up a small outpost. Would you go to Bahrum's Post and check in on the sergeant?", sourceObjective = "Speak with Sergeant Bahrum at Bahrum's Post.", completion = "It's a good thing the Senator didn't come out here on his own. It's dangerous, and we're going to need all the help we can get to get the situation under control.", sourceObjectiveStatus = "unverified-source-field" }
quests[25987] = { id = 25987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put It On", description = "Hey, {name}, I've got an idea for a disguise! Take one of these merciless whatchamacallits and put it on your head.\n\nWhat could possibly go wrong?\n\nReady to put it on?", sourceObjective = "Witness what occurs when you place the Merciless One on your head.", completion = "What happened? That thing wasn't completely dead! Maybe I should stick to mechanical stuff.\n\nIt gave you a vision? Of killing all of us?! That doesn't sound good.\n\nWell, in any case, that Earthen Ring fellow, Erunak Stonespeaker, wants these specimens all taken out to him. I'll make sure he gets them. I don't want them anywhere near me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25988] = { id = 25988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put It On", description = "I've got an idea for a sweet disguise, but I'm going to need your help, {name}! Take one of these merciless corpses and put it on your head.\n\nI know, I know, but it's dead, so what could possibly go wrong other than you smelling bad for a day or two?\n\nReady to put it on?", sourceObjective = "Witness what occurs when you place the Merciless One on your head.", completion = "My bad. My name is Fiasco for a reason. I should have known that thing wasn't completely dead when it wiggled a little.\n\nYou say it gave you a vision? Of killing all of us?! That doesn't sound good.\n\nHrm, well that Earthen Ring fellow, Erunak Stonespeaker, wants these specimens all taken out to him. I'll make sure they get out there. It's not like I want them stinking up the place around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25989] = { id = 25989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture the Crab", description = "Everything in my body tells me that Nespirah is trying to speak with me, but I cannot hear her.  Perhaps the naga have done something to her voice.\n\n<Duarn thinks to himself for a moment.>\n\nNespirah's voice may be suppressed... that means... we need to find a voice for her!\n\nI've got it!  The Idra'kess have been known to train deepseeker crabs as battle companions.  Use this net to capture a crab, and bring it to me.  You will likely find them prowling the chamber's outer edges.", sourceObjective = "Use Duarn's Net to capture a Deepseeker Crab inside of Nespirah.", progress = "I hope this works.  My skills as a shaman are limited, and I fear that this task may be too much for us.", completion = "<Duarn looks at the crab and disguises a frown.>\n\nIt doesn't look very impressive, does it?", sourceObjectiveStatus = "unverified-source-field" }
quests[25990] = { id = 25990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Through", description = "A trained shaman has the ability to communicate with the four elements of earth, fire, air and water.  This is known.\n\nWhat is not as widely known, however, is the presence of a fifth element.  This element is not as clearly described as the other four, but it has to do with the shared... commonality between all living creatures.\n\nMy theory is that the crab, as a creature of the sea, is close enough to Nespirah that, with the elements' coaxing, we can convince it to act as Nespirah's mouthpiece.", sourceObjective = "Observe as Earthmender Duarn attempts to speak with Nespirah.", progress = "The ritual is not yet complete, {name}.", completion = "I had assumed that the naga were only here for those pearls.  No, this makes much more sense.  If they had Nespirah's power under their control, the amount of damage the naga could do would be catastrophic!\n\nSomething must be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[25991] = { id = 25991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Are Not Alone", description = "<Duarn closes his eyes, pauses, and nods.>\n\nNespirah has just informed me that we are not the only people fighting inside of this shell.  A small group of Horde slaves has escaped and is currently fighting off the naga on the other side of the shell, up on the ledge that overlooks Nespirah's heart.\n\nGo find them, {name}, and see what help they can lend us.  With their aid, we may be able to rouse Nespirah from her torpor.\n\nI will remain here, should you need anything.", sourceObjective = "Find the Horde survivors inside of Nespirah in Vashj'ir.", completion = "{name}... is that you?", sourceObjectiveStatus = "unverified-source-field" }
quests[25992] = { id = 25992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hopelessly Gearless", description = "I honestly don't know how we've survived this long.  The naga took my armor and weapons, and left me with rags and a mining pick... and THAT snapped in half long ago.\n\nIf we're to stand any hope of turning the tide, I'm going to need something to fight with... as will my companions, though they may be too proud to admit it.\n\nI've seen weapon racks in the naga storage areas nearby.  I'm not accustomed to fighting with a trident, but it'll sure be better than fighting with my fists.", sourceObjective = "Obtain 4 Purloined Polearms from the weapon racks inside of Nespirah.", progress = "In my youth, I was given some training on spearfighting.\n\n\"Stick them with the pointy end,\" I think it was.", completion = "<Captain Vilethorn admires the polearms you present him.>\n\nOh, I'm sorry.  I was just imagining what these will look like with little bits of naga stuck to the ends of them.  Thank you, {name}.  We'll put these to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[25993] = { id = 25993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body Blows", description = "<Legionnaire Nazgrim listens intently to your recount of Duarn and Nespirah's conversation.>\n\nI see.  So the creature wants our help waking it up, is that it?\n\nWith hundreds of slaves already picking away at her pearls, the beast seems to be a pretty heavy sleeper.  You might have better luck, though.\n\nMy suggestion?  Look around the creature's flesh for signs of weakness.  Maybe that weapon of yours will find a ticklish spot and force the beast to come to its senses.", sourceObjective = "Attack 7 Nespirah Abscesses along the walls of Nespirah's body chamber.", completion = "Hopefully we made some progress.  I'm not sure how we'll know when the creature wakes up, but something tells me that it will be pretty obvious when it does.", sourceObjectiveStatus = "unverified-source-field" }
quests[25994] = { id = 25994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Valuable", description = "My time in the pearl pits, however short, has made me curious about the naga's goals.  Yes, I now know that the naga want to use Nespirah as an engine of war, but if that's the case, then why are they enslaving men to mine her pearls?\n\nAssuming we escape this creature's hull, I would very much like to study these objects.  The pearls we found in the pits were much too large to carry, but I've seen the warlords and prophets occasionally carrying around smaller ones.", sourceObjective = "Obtain 5 Mysterious Pearls from Idra'kess Warlords and Idra'kess Prophets inside of Nespirah.", progress = "The naga must have some ulterior motive with these pearls.  If I had time to study them, I'm certain I could figure it out.", completion = "Brilliant work!\n\n<Tulra tucks the pearls away beneath her armor.>\n\nNow I just need you and Legionnaire Nazgrim to get me safely out of here.  I can handle the studies from there on.", sourceObjectiveStatus = "unverified-source-field" }
quests[25995] = { id = 25995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overseer Idra'kess", description = "My men are flagging, {name}.  We won't last much longer against these naga, I'm afraid.  With the Idra'kess' weapons, and Nespirah's pearls, we should be ready to bust out of here.\n\nFollow the wall northeast, and look for a ramp to the upper chamber.  I assume their leader is in there, or perhaps the key to Nespirah's awakening.  Hopefully both.\n\nIf you feel strong enough, head up to the top of the shell and look for some answers.  Hellscream's eyes are upon you!", sourceObjective = "Head to the top of Nespirah and slay Overseer Idra'kess.", completion = "No need to bring me up to speed... Nespirah has been narrating your adventures as they happened, and Legionnaire Nazgrim filled me in on the rest.\n\n<Duarn closes his eyes and nods.>\n\nNespirah says that she is quite grateful, and that she has a small surprise ready for the naga.", sourceObjectiveStatus = "unverified-source-field" }
